/* =====================================================================
   3. RIGID-BODY PHYSICS
   Convex polygons, SAT + reference-face clipping, persistent manifolds
   with warm starting, sequential impulses (Coulomb friction, restitution),
   split-impulse position correction, speculative contacts against
   tunnelling, and per-body sleeping.
   ===================================================================== */

// Area, centroid and unit-density inertia (about the centroid) of a CCW polygon.
function polygonMassData(v) {
  const ox = v[0][0], oy = v[0][1];
  let area = 0, cx = 0, cy = 0, I = 0;
  for (let i = 1; i < v.length - 1; i++) {
    const e1x = v[i][0] - ox, e1y = v[i][1] - oy;
    const e2x = v[i + 1][0] - ox, e2y = v[i + 1][1] - oy;
    const D = e1x * e2y - e1y * e2x;
    const tri = 0.5 * D;
    area += tri;
    cx += tri * (e1x + e2x) / 3;
    cy += tri * (e1y + e2y) / 3;
    const ix = e1x * e1x + e2x * e1x + e2x * e2x;
    const iy = e1y * e1y + e2y * e1y + e2y * e2y;
    I += (0.25 / 3) * D * (ix + iy);
  }
  cx /= area; cy /= area;
  return { area, cx: cx + ox, cy: cy + oy, Iunit: I - area * (cx * cx + cy * cy) };
}

class Shape {
  constructor(verts, props) {
    const n = verts.length;
    this.n = n;
    this.id = -1;
    this.body = null;
    this.kind = props.kind;
    this.friction = props.friction;
    this.restitution = props.restitution;
    this.wheelIndex = props.wheelIndex ?? -1;
    this.lx = new Float64Array(n); this.ly = new Float64Array(n);
    this.lnx = new Float64Array(n); this.lny = new Float64Array(n);
    this.wx = new Float64Array(n); this.wy = new Float64Array(n);
    this.wnx = new Float64Array(n); this.wny = new Float64Array(n);
    this.minX = 0; this.minY = 0; this.maxX = 0; this.maxY = 0;
    this.setLocal(verts);
  }
  setLocal(verts) {
    const n = this.n;
    for (let i = 0; i < n; i++) { this.lx[i] = verts[i][0]; this.ly[i] = verts[i][1]; }
    for (let i = 0; i < n; i++) {
      const j = (i + 1) % n;
      const ex = this.lx[j] - this.lx[i], ey = this.ly[j] - this.ly[i];
      const len = Math.hypot(ex, ey);
      this.lnx[i] = ey / len; this.lny[i] = -ex / len;
    }
  }
  update(x, y, c, s) {
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (let i = 0; i < this.n; i++) {
      const lx = this.lx[i], ly = this.ly[i];
      const wx = x + c * lx - s * ly, wy = y + s * lx + c * ly;
      this.wx[i] = wx; this.wy[i] = wy;
      this.wnx[i] = c * this.lnx[i] - s * this.lny[i];
      this.wny[i] = s * this.lnx[i] + c * this.lny[i];
      if (wx < minX) minX = wx; if (wx > maxX) maxX = wx;
      if (wy < minY) minY = wy; if (wy > maxY) maxY = wy;
    }
    this.minX = minX; this.minY = minY; this.maxX = maxX; this.maxY = maxY;
  }
}

class Body {
  constructor(kind) {
    this.kind = kind;
    this.index = -1; this.layer = -1;
    this.x = 0; this.y = 0; this.a = 0; this.c = 1; this.s = 0;
    this.vx = 0; this.vy = 0; this.w = 0;
    this.pvx = 0; this.pvy = 0; this.pw = 0;       // split-impulse pseudo velocities
    this.fx = 0; this.fy = 0;
    this.mass = 0; this.invMass = 0; this.I = 0; this.invI = 0;
    this.im = 0; this.iI = 0;                      // effective (0 while asleep)
    this.shapes = []; this.radius = 0;
    this.isStatic = false;
    this.sleeping = false; this.sleepTimer = 0; this.canSleep = true; this.motion2 = 0;
    this.minX = 0; this.minY = 0; this.maxX = 0; this.maxY = 0; this.ext = 0; this.key = 0;
    this.px = 0; this.py = 0; this.pa = 0;        // previous frame pose (render interpolation)
    this.x0 = 0; this.y0 = 0; this.a0 = 0;        // initial pose
  }
  addShape(shape) {
    shape.body = this;
    this.shapes.push(shape);
    for (let i = 0; i < shape.n; i++) this.radius = Math.max(this.radius, Math.hypot(shape.lx[i], shape.ly[i]));
  }
  setMass(m, I) {
    this.mass = m; this.invMass = m > 0 ? 1 / m : 0;
    this.I = I; this.invI = I > 0 ? 1 / I : 0;
  }
  sync() {
    this.c = Math.cos(this.a); this.s = Math.sin(this.a);
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (let k = 0; k < this.shapes.length; k++) {
      const sh = this.shapes[k];
      sh.update(this.x, this.y, this.c, this.s);
      if (sh.minX < minX) minX = sh.minX; if (sh.maxX > maxX) maxX = sh.maxX;
      if (sh.minY < minY) minY = sh.minY; if (sh.maxY > maxY) maxY = sh.maxY;
    }
    this.minX = minX; this.minY = minY; this.maxX = maxX; this.maxY = maxY;
  }
  wake() {
    if (!this.sleeping) return;
    this.sleeping = false; this.sleepTimer = 0;
    this.im = this.invMass; this.iI = this.invI;
    this.pvx = this.pvy = this.pw = 0;
    this.motion2 = 0;
  }
}

/* ---------- narrow phase ---------- */

// Scratch output of the collision routines (normal points from shape A to shape B).
const CP = { n: 0, nx: 0, ny: 0, minSep: 0, x: new Float64Array(4), y: new Float64Array(4), sep: new Float64Array(4), id: new Int32Array(4) };
const SEP = { v: 0, i: 0 };

function cpPush(x, y, sep, id) {
  if (CP.n >= 4) return;
  const k = CP.n++;
  CP.x[k] = x; CP.y[k] = y; CP.sep[k] = sep; CP.id[k] = id;
  if (sep < CP.minSep) CP.minSep = sep;
}

function maxSeparation(A, B) {
  let best = -Infinity, bestI = 0;
  const bn = B.n, bx = B.wx, by = B.wy;
  for (let i = 0; i < A.n; i++) {
    const nx = A.wnx[i], ny = A.wny[i], vx = A.wx[i], vy = A.wy[i];
    let si = Infinity;
    for (let j = 0; j < bn; j++) {
      const d = nx * (bx[j] - vx) + ny * (by[j] - vy);
      if (d < si) si = d;
    }
    if (si > best) { best = si; bestI = i; }
  }
  SEP.v = best; SEP.i = bestI;
}

function collidePolys(A, B, margin) {
  CP.n = 0; CP.minSep = Infinity;
  maxSeparation(A, B);
  const sepA = SEP.v, edgeA = SEP.i;
  if (sepA > margin) return;
  maxSeparation(B, A);
  const sepB = SEP.v, edgeB = SEP.i;
  if (sepB > margin) return;

  let R, I, e, flip;
  if (sepB > sepA + 0.1 * SIM.slop) { R = B; I = A; e = edgeB; flip = 1; }
  else { R = A; I = B; e = edgeA; flip = 0; }

  const e2 = (e + 1) % R.n;
  const v1x = R.wx[e], v1y = R.wy[e], v2x = R.wx[e2], v2y = R.wy[e2];
  const nx = R.wnx[e], ny = R.wny[e];

  // Incident edge: the one most anti-parallel to the reference normal.
  let k = 0, minD = Infinity;
  for (let j = 0; j < I.n; j++) {
    const d = nx * I.wnx[j] + ny * I.wny[j];
    if (d < minD) { minD = d; k = j; }
  }
  const k2 = (k + 1) % I.n;
  let ax = I.wx[k], ay = I.wy[k], aid = k;
  let bx = I.wx[k2], by = I.wy[k2], bid = k2;

  let tx = v2x - v1x, ty = v2y - v1y;
  const tl = Math.hypot(tx, ty); tx /= tl; ty /= tl;

  // Clip the incident segment against the two side planes of the reference edge.
  const off1 = tx * v1x + ty * v1y;
  let da = off1 - (tx * ax + ty * ay), db = off1 - (tx * bx + ty * by);
  if (da > 0 && db > 0) return;
  if (da > 0) { const u = da / (da - db); ax += u * (bx - ax); ay += u * (by - ay); aid = 32 + k; }
  else if (db > 0) { const u = db / (db - da); bx += u * (ax - bx); by += u * (ay - by); bid = 32 + k; }

  const off2 = tx * v2x + ty * v2y;
  da = tx * ax + ty * ay - off2; db = tx * bx + ty * by - off2;
  if (da > 0 && db > 0) return;
  if (da > 0) { const u = da / (da - db); ax += u * (bx - ax); ay += u * (by - ay); aid = 48 + k; }
  else if (db > 0) { const u = db / (db - da); bx += u * (ax - bx); by += u * (ay - by); bid = 48 + k; }

  CP.nx = flip ? -nx : nx;
  CP.ny = flip ? -ny : ny;
  const base = (flip << 14) | (e << 8);
  const sa = nx * (ax - v1x) + ny * (ay - v1y);
  const sb = nx * (bx - v1x) + ny * (by - v1y);
  if (sa <= margin) cpPush(ax - nx * sa * 0.5, ay - ny * sa * 0.5, sa, base | aid);
  if (sb <= margin) cpPush(bx - nx * sb * 0.5, by - ny * sb * 0.5, sb, base | bid);
}

// Ground is the half-plane y <= 0 (static body A, normal +y).
function collideGround(S, margin) {
  CP.n = 0; CP.minSep = Infinity; CP.nx = 0; CP.ny = 1;
  for (let j = 0; j < S.n; j++) {
    const y = S.wy[j];
    if (y <= margin) cpPush(S.wx[j], y * 0.5, y, j);
  }
}

/* ---------- contact manifolds ---------- */

class ContactPoint {
  constructor() {
    this.id = 0; this.x = 0; this.y = 0; this.sep = 0;
    this.jn = 0; this.jt = 0; this.jp = 0;
    this.rax = 0; this.ray = 0; this.rbx = 0; this.rby = 0;
    this.mn = 0; this.mt = 0; this.vt = 0;
  }
}

const OLD_ID = new Int32Array(4), OLD_JN = new Float64Array(4), OLD_JT = new Float64Array(4);

// Kinds: 0 brick-brick, 1 ground-brick, 2 car-brick, 3 ground-car
class Manifold {
  constructor(sa, sb) {
    this.sa = sa; this.sb = sb; this.a = sa.body; this.b = sb.body;
    this.count = 0; this.stamp = 0; this.nx = 0; this.ny = 1;
    this.mu0 = Math.sqrt(sa.friction * sb.friction);
    this.mu = this.mu0;
    this.e = Math.max(sa.restitution, sb.restitution);
    this.wheelGround = sa.kind === 'ground' && sb.kind === 'wheel';
    const carA = this.a.kind === 'car', carB = this.b.kind === 'car';
    this.kind = sa.kind === 'ground' ? (carB ? 3 : 1) : (carA || carB ? 2 : 0);
    this.vnMin = 0;
    this.p = [new ContactPoint(), new ContactPoint(), new ContactPoint(), new ContactPoint()];
  }
  update(stamp) {
    const oldN = this.count;
    for (let k = 0; k < oldN; k++) { OLD_ID[k] = this.p[k].id; OLD_JN[k] = this.p[k].jn; OLD_JT[k] = this.p[k].jt; }
    for (let i = 0; i < CP.n; i++) {
      const p = this.p[i];
      p.id = CP.id[i]; p.x = CP.x[i]; p.y = CP.y[i]; p.sep = CP.sep[i];
      p.jn = 0; p.jt = 0;
      for (let k = 0; k < oldN; k++) {
        if (OLD_ID[k] === p.id) { p.jn = OLD_JN[k]; p.jt = OLD_JT[k]; break; }
      }
    }
    this.count = CP.n; this.nx = CP.nx; this.ny = CP.ny; this.stamp = stamp;
  }
}

/* ---------- solver kernels ---------- */

function prestep(m, invH) {
  const A = m.a, B = m.b, imA = A.im, iIA = A.iI, imB = B.im, iIB = B.iI;
  const nx = m.nx, ny = m.ny, tx = ny, ty = -nx, n = m.count, P = m.p;
  let vnMin = 0;
  for (let i = 0; i < n; i++) {
    const p = P[i];
    const rax = p.x - A.x, ray = p.y - A.y, rbx = p.x - B.x, rby = p.y - B.y;
    p.rax = rax; p.ray = ray; p.rbx = rbx; p.rby = rby;
    const rnA = rax * ny - ray * nx, rnB = rbx * ny - rby * nx;
    const kN = imA + imB + iIA * rnA * rnA + iIB * rnB * rnB;
    p.mn = kN > 0 ? 1 / kN : 0;
    const rtA = rax * ty - ray * tx, rtB = rbx * ty - rby * tx;
    const kT = imA + imB + iIA * rtA * rtA + iIB * rtB * rtB;
    p.mt = kT > 0 ? 1 / kT : 0;
    const dvx = B.vx - B.w * rby - A.vx + A.w * ray;
    const dvy = B.vy + B.w * rbx - A.vy - A.w * rax;
    const vn = dvx * nx + dvy * ny;
    if (vn < vnMin && p.sep < 0.02) vnMin = vn;
    // Speculative: a separated point may close its gap this substep but no further.
    let target = p.sep > 0 ? -p.sep * invH : 0;
    if (vn < -SIM.restitutionThreshold && p.sep < SIM.slop) {
      const bounce = -m.e * vn;
      if (bounce > target) target = bounce;
    }
    p.vt = target;
    p.jp = 0;
    if (p.sep > 2 * SIM.slop) { p.jn = 0; p.jt = 0; }
  }
  m.vnMin = vnMin;
  for (let i = 0; i < n; i++) {
    const p = P[i];
    const Px = p.jn * nx + p.jt * tx, Py = p.jn * ny + p.jt * ty;
    A.vx -= imA * Px; A.vy -= imA * Py; A.w -= iIA * (p.rax * Py - p.ray * Px);
    B.vx += imB * Px; B.vy += imB * Py; B.w += iIB * (p.rbx * Py - p.rby * Px);
  }
}

function solveVelocity(m) {
  const A = m.a, B = m.b, imA = A.im, iIA = A.iI, imB = B.im, iIB = B.iI;
  const nx = m.nx, ny = m.ny, tx = ny, ty = -nx, mu = m.mu, n = m.count, P = m.p;
  let vAx = A.vx, vAy = A.vy, wA = A.w, vBx = B.vx, vBy = B.vy, wB = B.w;
  for (let i = 0; i < n; i++) {
    const p = P[i];
    const dvx = vBx - wB * p.rby - vAx + wA * p.ray;
    const dvy = vBy + wB * p.rbx - vAy - wA * p.rax;
    const vt = dvx * tx + dvy * ty;
    const maxF = mu * p.jn;
    const nj = clamp(p.jt - p.mt * vt, -maxF, maxF);
    const lam = nj - p.jt; p.jt = nj;
    const Px = lam * tx, Py = lam * ty;
    vAx -= imA * Px; vAy -= imA * Py; wA -= iIA * (p.rax * Py - p.ray * Px);
    vBx += imB * Px; vBy += imB * Py; wB += iIB * (p.rbx * Py - p.rby * Px);
  }
  for (let i = 0; i < n; i++) {
    const p = P[i];
    const dvx = vBx - wB * p.rby - vAx + wA * p.ray;
    const dvy = vBy + wB * p.rbx - vAy - wA * p.rax;
    const vn = dvx * nx + dvy * ny;
    const nj = Math.max(p.jn + p.mn * (p.vt - vn), 0);
    const lam = nj - p.jn; p.jn = nj;
    const Px = lam * nx, Py = lam * ny;
    vAx -= imA * Px; vAy -= imA * Py; wA -= iIA * (p.rax * Py - p.ray * Px);
    vBx += imB * Px; vBy += imB * Py; wB += iIB * (p.rbx * Py - p.rby * Px);
  }
  A.vx = vAx; A.vy = vAy; A.w = wA; B.vx = vBx; B.vy = vBy; B.w = wB;
}

// Split impulse: penetration is removed through pseudo velocities that never
// feed back into real momentum, so overlap recovery cannot launch bricks.
function solvePosition(m, invH) {
  const A = m.a, B = m.b, imA = A.im, iIA = A.iI, imB = B.im, iIB = B.iI;
  const nx = m.nx, ny = m.ny, n = m.count, P = m.p;
  for (let i = 0; i < n; i++) {
    const p = P[i];
    let target;
    if (p.sep > 0) target = -p.sep * invH;
    else if (p.sep < -SIM.slop) target = SIM.beta * Math.min(-(p.sep + SIM.slop), SIM.maxCorrection) * invH;
    else target = 0;
    const dvx = B.pvx - B.pw * p.rby - A.pvx + A.pw * p.ray;
    const dvy = B.pvy + B.pw * p.rbx - A.pvy - A.pw * p.rax;
    const vn = dvx * nx + dvy * ny;
    const nj = Math.max(p.jp + p.mn * (target - vn), 0);
    const lam = nj - p.jp; p.jp = nj;
    const Px = lam * nx, Py = lam * ny;
    A.pvx -= imA * Px; A.pvy -= imA * Py; A.pw -= iIA * (p.rax * Py - p.ray * Px);
    B.pvx += imB * Px; B.pvy += imB * Py; B.pw += iIB * (p.rbx * Py - p.rby * Px);
  }
}

function sortByKey(L) {
  for (let i = 0; i < L.length; i++) { const b = L[i]; b.key = b.minX - b.ext; }
  for (let i = 1; i < L.length; i++) {
    const b = L[i], k = b.key;
    let j = i - 1;
    while (j >= 0 && L[j].key > k) { L[j + 1] = L[j]; j--; }
    L[j + 1] = b;
  }
}

/* ---------- world ---------- */

class World {
  constructor(settings) {
    this.gravity = settings.gravity;
    this.groundFriction = settings.groundFriction;
    this.bodies = [];
    this.bricks = [];
    this.layers = [];
    for (let k = 0; k < settings.layers; k++) this.layers.push([]);
    this.car = null;
    this.wheelsLocked = false;
    this.manifolds = new Map();
    this.active = [];
    this.stamp = 0;
    this.nextShapeId = 1;
    this.ground = new Body('ground');
    this.ground.isStatic = true;
    this.groundShape = { id: 0, body: this.ground, kind: 'ground', friction: settings.groundFriction, restitution: 0 };
    this.events = [];
    this.carTouch = false;
    this.wheelContact = [false, false];
  }

  add(body) {
    body.index = this.bodies.length;
    this.bodies.push(body);
    for (const sh of body.shapes) sh.id = this.nextShapeId++;
    body.sync();
    body.x0 = body.x; body.y0 = body.y; body.a0 = body.a;
    body.px = body.x; body.py = body.y; body.pa = body.a;
    if (body.kind === 'brick') { this.bricks.push(body); this.layers[body.layer].push(body); }
    if (body.kind === 'car') this.car = body;
    return body;
  }

  touch(sa, sb, stamp) {
    const key = sa.id * 8192 + sb.id;
    let m = this.manifolds.get(key);
    if (!m) { m = new Manifold(sa, sb); this.manifolds.set(key, m); }
    m.update(stamp);
    this.active.push(m);
    return m;
  }

  collide() {
    const stamp = ++this.stamp;
    const base = SIM.specBase;
    this.active.length = 0;
    this.carTouch = false;
    this.wheelContact[0] = this.wheelContact[1] = false;

    // Ground (static half-plane).
    for (let i = 0; i < this.bodies.length; i++) {
      const b = this.bodies[i];
      if (b.sleeping) continue;
      const margin = base + b.ext;
      if (b.minY > margin) continue;
      for (let s = 0; s < b.shapes.length; s++) {
        const sh = b.shapes[s];
        if (sh.minY > margin) continue;
        collideGround(sh, margin);
        if (CP.n) {
          this.touch(this.groundShape, sh, stamp);
          if (sh.wheelIndex >= 0 && CP.minSep < 0.01) this.wheelContact[sh.wheelIndex] = true;
        }
      }
    }

    // Bricks, per depth layer (layers are separate wythes and do not touch each other).
    for (let l = 0; l < this.layers.length; l++) {
      const L = this.layers[l];
      sortByKey(L);
      const n = L.length;
      for (let i = 0; i < n; i++) {
        const a = L[i];
        const aMax = a.maxX + a.ext;
        for (let j = i + 1; j < n; j++) {
          const b = L[j];
          if (b.key > aMax) break;
          if (a.sleeping && b.sleeping) continue;
          if (a.minY - a.ext > b.maxY + b.ext || b.minY - b.ext > a.maxY + a.ext) continue;
          let sa = a.shapes[0], sb = b.shapes[0];
          if (sa.id > sb.id) { const t = sa; sa = sb; sb = t; }
          collidePolys(sa, sb, base + a.ext + b.ext);
          if (CP.n) this.touch(sa, sb, stamp);
        }
      }
    }

    // Car against every brick in every layer (the car spans the full wall depth).
    const car = this.car;
    if (car) {
      for (let i = 0; i < this.bricks.length; i++) {
        const b = this.bricks[i];
        if (car.sleeping && b.sleeping) continue;
        const ext = car.ext + b.ext;
        if (b.minX > car.maxX + ext || b.maxX < car.minX - ext || b.minY > car.maxY + ext || b.maxY < car.minY - ext) continue;
        const bs = b.shapes[0];
        for (let s = 0; s < car.shapes.length; s++) {
          const cs = car.shapes[s];
          if (b.minX > cs.maxX + ext || b.maxX < cs.minX - ext || b.minY > cs.maxY + ext || b.maxY < cs.minY - ext) continue;
          collidePolys(cs, bs, base + ext);
          if (CP.n) {
            this.touch(cs, bs, stamp);
            if (CP.minSep < 0.01) this.carTouch = true;
          }
        }
      }
    }

    // Drop manifolds that were not refreshed, unless both sides are at rest
    // (kept so a woken brick restarts with its resting impulses).
    for (const [key, m] of this.manifolds) {
      if (m.stamp === stamp) continue;
      if ((m.a.sleeping || m.a.isStatic) && (m.b.sleeping || m.b.isStatic)) continue;
      this.manifolds.delete(key);
    }
  }

  wakeTouching() {
    const w2 = SIM.wakeSpeed * SIM.wakeSpeed;
    for (let i = 0; i < this.active.length; i++) {
      const m = this.active[i], A = m.a, B = m.b;
      if (A.sleeping && !B.sleeping && !B.isStatic && B.motion2 > w2) A.wake();
      else if (B.sleeping && !A.sleeping && !A.isStatic && A.motion2 > w2) B.wake();
    }
  }

  substep(h) {
    const invH = 1 / h, g = this.gravity, bodies = this.bodies;
    const ld = 1 / (1 + h * SIM.linDamp), ad = 1 / (1 + h * SIM.angDamp);

    for (let i = 0; i < bodies.length; i++) {
      const b = bodies[i];
      if (b.sleeping) { b.im = 0; b.iI = 0; b.ext = 0; continue; }
      b.im = b.invMass; b.iI = b.invI;
      b.vx = (b.vx + b.fx * b.invMass * h) * ld;
      b.vy = (b.vy + (b.fy * b.invMass - g) * h) * ld;
      b.w *= ad;
      b.pvx = 0; b.pvy = 0; b.pw = 0;
      const sp = Math.sqrt(b.vx * b.vx + b.vy * b.vy) + Math.abs(b.w) * b.radius;
      b.ext = Math.min(SIM.maxExt, 0.004 + sp * h * 1.25);
    }

    this.collide();
    this.wakeTouching();

    const act = this.active, nA = act.length;
    const lockedMu = this.groundFriction;
    for (let i = 0; i < nA; i++) {
      const m = act[i];
      if (m.wheelGround) m.mu = this.wheelsLocked ? lockedMu : SIM.rollingMu;
      prestep(m, invH);
    }
    for (let it = 0; it < SIM.velIters; it++) for (let i = 0; i < nA; i++) solveVelocity(act[i]);
    for (let it = 0; it < SIM.posIters; it++) for (let i = 0; i < nA; i++) solvePosition(act[i], invH);

    for (let i = 0; i < nA; i++) {
      const m = act[i];
      if (m.vnMin < -2.5 && this.events.length < 96) {
        const p = m.p[0];
        this.events.push({ x: p.x, y: p.y, s: -m.vnMin, k: m.kind, nx: m.nx, ny: m.ny });
      }
    }

    const vMax2 = SIM.maxV * SIM.maxV;
    const sl2 = SIM.sleepLin * SIM.sleepLin, sa2 = SIM.sleepAng * SIM.sleepAng;
    for (let i = 0; i < bodies.length; i++) {
      const b = bodies[i];
      if (b.sleeping || b.isStatic) continue;
      let v2 = b.vx * b.vx + b.vy * b.vy;
      if (v2 > vMax2) { const k = SIM.maxV / Math.sqrt(v2); b.vx *= k; b.vy *= k; v2 = vMax2; }
      b.w = clamp(b.w, -SIM.maxW, SIM.maxW);
      b.x += (b.vx + b.pvx) * h;
      b.y += (b.vy + b.pvy) * h;
      b.a += (b.w + b.pw) * h;
      b.sync();
      const w2 = b.w * b.w;
      b.motion2 = v2 + w2 * b.radius * b.radius;
      if (b.canSleep && v2 < sl2 && w2 < sa2) {
        b.sleepTimer += h;
        if (b.sleepTimer >= SIM.sleepTime) {
          b.sleeping = true; b.vx = 0; b.vy = 0; b.w = 0; b.im = 0; b.iI = 0; b.motion2 = 0;
        }
      } else {
        b.sleepTimer = 0;
      }
    }
  }

  // Solve the resting wall once at build time so the first woken bricks start
  // with equilibrium contact impulses instead of sagging. Positions do not move.
  prestress(h, rounds) {
    const invH = 1 / h;
    for (const b of this.bodies) { b.sleeping = false; b.im = b.invMass; b.iI = b.invI; b.ext = 0; }
    this.collide();
    const act = this.active;
    for (let r = 0; r < rounds; r++) {
      for (const b of this.bodies) { if (b.isStatic) continue; b.vx = 0; b.w = 0; b.vy = -this.gravity * h; }
      for (let i = 0; i < act.length; i++) {
        const m = act[i];
        if (m.wheelGround) m.mu = SIM.rollingMu;
        prestep(m, invH);
      }
      for (let it = 0; it < SIM.velIters; it++) for (let i = 0; i < act.length; i++) solveVelocity(act[i]);
    }
    for (const b of this.bodies) {
      if (b.isStatic) continue;
      b.vx = 0; b.vy = 0; b.w = 0; b.motion2 = 0;
      if (b.kind === 'brick') { b.sleeping = true; b.im = 0; b.iI = 0; }
    }
    this.events.length = 0;
  }
}

/*__EXPERIMENT__*/

/* =====================================================================
   3. RIGID-BODY PHYSICS
   Convex polygons, SAT + reference-face clipping, persistent manifolds
   with warm starting, sequential impulses (Coulomb friction, restitution),
   split-impulse position correction, speculative contacts against
   tunnelling, and per-body sleeping.
   ===================================================================== */

// Area, centroid and unit-density inertia (about the centroid) of a CCW polygon.
function polygonMassData(v) {
  const ox = v[0][0], oy = v[0][1];
  let area = 0, cx = 0, cy = 0, I = 0;
  for (let i = 1; i < v.length - 1; i++) {
    const e1x = v[i][0] - ox, e1y = v[i][1] - oy;
    const e2x = v[i + 1][0] - ox, e2y = v[i + 1][1] - oy;
    const D = e1x * e2y - e1y * e2x;
    const tri = 0.5 * D;
    area += tri;
    cx += tri * (e1x + e2x) / 3;
    cy += tri * (e1y + e2y) / 3;
    const ix = e1x * e1x + e2x * e1x + e2x * e2x;
    const iy = e1y * e1y + e2y * e1y + e2y * e2y;
    I += (0.25 / 3) * D * (ix + iy);
  }
  cx /= area; cy /= area;
  return { area, cx: cx + ox, cy: cy + oy, Iunit: I - area * (cx * cx + cy * cy) };
}

class Shape {
  constructor(verts, props) {
    const n = verts.length;
    this.n = n;
    this.id = -1;
    this.body = null;
    this.kind = props.kind;
    this.friction = props.friction;
    this.restitution = props.restitution;
    this.wheelIndex = props.wheelIndex ?? -1;
    this.lx = new Float64Array(n); this.ly = new Float64Array(n);
    this.lnx = new Float64Array(n); this.lny = new Float64Array(n);
    this.wx = new Float64Array(n); this.wy = new Float64Array(n);
    this.wnx = new Float64Array(n); this.wny = new Float64Array(n);
    this.minX = 0; this.minY = 0; this.maxX = 0; this.maxY = 0;
    this.setLocal(verts);
  }
  setLocal(verts) {
    const n = this.n;
    for (let i = 0; i < n; i++) { this.lx[i] = verts[i][0]; this.ly[i] = verts[i][1]; }
    for (let i = 0; i < n; i++) {
      const j = (i + 1) % n;
      const ex = this.lx[j] - this.lx[i], ey = this.ly[j] - this.ly[i];
      const len = Math.hypot(ex, ey);
      this.lnx[i] = ey / len; this.lny[i] = -ex / len;
    }
  }
  update(x, y, c, s) {
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (let i = 0; i < this.n; i++) {
      const lx = this.lx[i], ly = this.ly[i];
      const wx = x + c * lx - s * ly, wy = y + s * lx + c * ly;
      this.wx[i] = wx; this.wy[i] = wy;
      this.wnx[i] = c * this.lnx[i] - s * this.lny[i];
      this.wny[i] = s * this.lnx[i] + c * this.lny[i];
      if (wx < minX) minX = wx; if (wx > maxX) maxX = wx;
      if (wy < minY) minY = wy; if (wy > maxY) maxY = wy;
    }
    this.minX = minX; this.minY = minY; this.maxX = maxX; this.maxY = maxY;
  }
}

class Body {
  constructor(kind) {
    this.kind = kind;
    this.index = -1; this.layer = -1;
    this.x = 0; this.y = 0; this.a = 0; this.c = 1; this.s = 0;
    this.vx = 0; this.vy = 0; this.w = 0;
    this.pvx = 0; this.pvy = 0; this.pw = 0;       // split-impulse pseudo velocities
    this.fx = 0; this.fy = 0;
    this.mass = 0; this.invMass = 0; this.I = 0; this.invI = 0;
    this.im = 0; this.iI = 0;                      // effective (0 while asleep)
    this.shapes = []; this.radius = 0;
    this.isStatic = false;
    this.sleeping = false; this.sleepTimer = 0; this.canSleep = true; this.motion2 = 0;
    this.minX = 0; this.minY = 0; this.maxX = 0; this.maxY = 0; this.ext = 0; this.key = 0;
    this.px = 0; this.py = 0; this.pa = 0;        // previous frame pose (render interpolation)
    this.x0 = 0; this.y0 = 0; this.a0 = 0;        // initial pose
  }
  addShape(shape) {
    shape.body = this;
    this.shapes.push(shape);
    for (let i = 0; i < shape.n; i++) this.radius = Math.max(this.radius, Math.hypot(shape.lx[i], shape.ly[i]));
  }
  setMass(m, I) {
    this.mass = m; this.invMass = m > 0 ? 1 / m : 0;
    this.I = I; this.invI = I > 0 ? 1 / I : 0;
  }
  sync() {
    this.c = Math.cos(this.a); this.s = Math.sin(this.a);
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (let k = 0; k < this.shapes.length; k++) {
      const sh = this.shapes[k];
      sh.update(this.x, this.y, this.c, this.s);
      if (sh.minX < minX) minX = sh.minX; if (sh.maxX > maxX) maxX = sh.maxX;
      if (sh.minY < minY) minY = sh.minY; if (sh.maxY > maxY) maxY = sh.maxY;
    }
    this.minX = minX; this.minY = minY; this.maxX = maxX; this.maxY = maxY;
  }
  wake() {
    if (!this.sleeping) return;
    this.sleeping = false; this.sleepTimer = 0;
    this.im = this.invMass; this.iI = this.invI;
    this.pvx = this.pvy = this.pw = 0;
    this.motion2 = 0;
  }
}

/* ---------- narrow phase ---------- */

// Scratch output of the collision routines (normal points from shape A to shape B).
const CP = { n: 0, nx: 0, ny: 0, minSep: 0, x: new Float64Array(4), y: new Float64Array(4), sep: new Float64Array(4), id: new Int32Array(4) };
const SEP = { v: 0, i: 0 };

function cpPush(x, y, sep, id) {
  if (CP.n >= 4) return;
  const k = CP.n++;
  CP.x[k] = x; CP.y[k] = y; CP.sep[k] = sep; CP.id[k] = id;
  if (sep < CP.minSep) CP.minSep = sep;
}

function maxSeparation(A, B) {
  let best = -Infinity, bestI = 0;
  const bn = B.n, bx = B.wx, by = B.wy;
  for (let i = 0; i < A.n; i++) {
    const nx = A.wnx[i], ny = A.wny[i], vx = A.wx[i], vy = A.wy[i];
    let si = Infinity;
    for (let j = 0; j < bn; j++) {
      const d = nx * (bx[j] - vx) + ny * (by[j] - vy);
      if (d < si) si = d;
    }
    if (si > best) { best = si; bestI = i; }
  }
  SEP.v = best; SEP.i = bestI;
}

function collidePolys(A, B, margin) {
  CP.n = 0; CP.minSep = Infinity;
  maxSeparation(A, B);
  const sepA = SEP.v, edgeA = SEP.i;
  if (sepA > margin) return;
  maxSeparation(B, A);
  const sepB = SEP.v, edgeB = SEP.i;
  if (sepB > margin) return;

  let R, I, e, flip;
  if (sepB > sepA + 0.1 * SIM.slop) { R = B; I = A; e = edgeB; flip = 1; }
  else { R = A; I = B; e = edgeA; flip = 0; }

  const e2 = (e + 1) % R.n;
  const v1x = R.wx[e], v1y = R.wy[e], v2x = R.wx[e2], v2y = R.wy[e2];
  const nx = R.wnx[e], ny = R.wny[e];

  // Incident edge: the one most anti-parallel to the reference normal.
  let k = 0, minD = Infinity;
  for (let j = 0; j < I.n; j++) {
    const d = nx * I.wnx[j] + ny * I.wny[j];
    if (d < minD) { minD = d; k = j; }
  }
  const k2 = (k + 1) % I.n;
  let ax = I.wx[k], ay = I.wy[k], aid = k;
  let bx = I.wx[k2], by = I.wy[k2], bid = k2;

  let tx = v2x - v1x, ty = v2y - v1y;
  const tl = Math.hypot(tx, ty); tx /= tl; ty /= tl;

  // Clip the incident segment against the two side planes of the reference edge.
  const off1 = tx * v1x + ty * v1y;
  let da = off1 - (tx * ax + ty * ay), db = off1 - (tx * bx + ty * by);
  if (da > 0 && db > 0) return;
  if (da > 0) { const u = da / (da - db); ax += u * (bx - ax); ay += u * (by - ay); aid = 32 + k; }
  else if (db > 0) { const u = db / (db - da); bx += u * (ax - bx); by += u * (ay - by); bid = 32 + k; }

  const off2 = tx * v2x + ty * v2y;
  da = tx * ax + ty * ay - off2; db = tx * bx + ty * by - off2;
  if (da > 0 && db > 0) return;
  if (da > 0) { const u = da / (da - db); ax += u * (bx - ax); ay += u * (by - ay); aid = 48 + k; }
  else if (db > 0) { const u = db / (db - da); bx += u * (ax - bx); by += u * (ay - by); bid = 48 + k; }

  CP.nx = flip ? -nx : nx;
  CP.ny = flip ? -ny : ny;
  const base = (flip << 14) | (e << 8);
  const sa = nx * (ax - v1x) + ny * (ay - v1y);
  const sb = nx * (bx - v1x) + ny * (by - v1y);
  if (sa <= margin) cpPush(ax - nx * sa * 0.5, ay - ny * sa * 0.5, sa, base | aid);
  if (sb <= margin) cpPush(bx - nx * sb * 0.5, by - ny * sb * 0.5, sb, base | bid);
}

// Ground is the half-plane y <= 0 (static body A, normal +y).
function collideGround(S, margin) {
  CP.n = 0; CP.minSep = Infinity; CP.nx = 0; CP.ny = 1;
  for (let j = 0; j < S.n; j++) {
    const y = S.wy[j];
    if (y <= margin) cpPush(S.wx[j], y * 0.5, y, j);
  }
}

/* ---------- contact manifolds ---------- */

class ContactPoint {
  constructor() {
    this.id = 0; this.x = 0; this.y = 0; this.sep = 0;
    this.jn = 0; this.jt = 0; this.jp = 0;
    this.rax = 0; this.ray = 0; this.rbx = 0; this.rby = 0;
    this.mn = 0; this.mt = 0; this.vt = 0;
  }
}

const OLD_ID = new Int32Array(4), OLD_JN = new Float64Array(4), OLD_JT = new Float64Array(4);

// Kinds: 0 brick-brick, 1 ground-brick, 2 car-brick, 3 ground-car
class Manifold {
  constructor(sa, sb) {
    this.sa = sa; this.sb = sb; this.a = sa.body; this.b = sb.body;
    this.count = 0; this.stamp = 0; this.nx = 0; this.ny = 1;
    this.mu0 = Math.sqrt(sa.friction * sb.friction);
    this.mu = this.mu0;
    this.e = Math.max(sa.restitution, sb.restitution);
    this.wheelGround = sa.kind === 'ground' && sb.kind === 'wheel';
    const carA = this.a.kind === 'car', carB = this.b.kind === 'car';
    this.kind = sa.kind === 'ground' ? (carB ? 3 : 1) : (carA || carB ? 2 : 0);
    this.vnMin = 0;
    this.p = [new ContactPoint(), new ContactPoint(), new ContactPoint(), new ContactPoint()];
  }
  update(stamp) {
    const oldN = this.count;
    for (let k = 0; k < oldN; k++) { OLD_ID[k] = this.p[k].id; OLD_JN[k] = this.p[k].jn; OLD_JT[k] = this.p[k].jt; }
    for (let i = 0; i < CP.n; i++) {
      const p = this.p[i];
      p.id = CP.id[i]; p.x = CP.x[i]; p.y = CP.y[i]; p.sep = CP.sep[i];
      p.jn = 0; p.jt = 0;
      for (let k = 0; k < oldN; k++) {
        if (OLD_ID[k] === p.id) { p.jn = OLD_JN[k]; p.jt = OLD_JT[k]; break; }
      }
    }
    this.count = CP.n; this.nx = CP.nx; this.ny = CP.ny; this.stamp = stamp;
  }
}

/* ---------- solver kernels ---------- */

function prestep(m, invH) {
  const A = m.a, B = m.b, imA = A.im, iIA = A.iI, imB = B.im, iIB = B.iI;
  const nx = m.nx, ny = m.ny, tx = ny, ty = -nx, n = m.count, P = m.p;
  let vnMin = 0;
  for (let i = 0; i < n; i++) {
    const p = P[i];
    const rax = p.x - A.x, ray = p.y - A.y, rbx = p.x - B.x, rby = p.y - B.y;
    p.rax = rax; p.ray = ray; p.rbx = rbx; p.rby = rby;
    const rnA = rax * ny - ray * nx, rnB = rbx * ny - rby * nx;
    const kN = imA + imB + iIA * rnA * rnA + iIB * rnB * rnB;
    p.mn = kN > 0 ? 1 / kN : 0;
    const rtA = rax * ty - ray * tx, rtB = rbx * ty - rby * tx;
    const kT = imA + imB + iIA * rtA * rtA + iIB * rtB * rtB;
    p.mt = kT > 0 ? 1 / kT : 0;
    const dvx = B.vx - B.w * rby - A.vx + A.w * ray;
    const dvy = B.vy + B.w * rbx - A.vy - A.w * rax;
    const vn = dvx * nx + dvy * ny;
    if (vn < vnMin && p.sep < 0.02) vnMin = vn;
    // Speculative: a separated point may close its gap this substep but no further.
    let target = p.sep > 0 ? -p.sep * invH : 0;
    if (vn < -SIM.restitutionThreshold && p.sep < SIM.slop) {
      const bounce = -m.e * vn;
      if (bounce > target) target = bounce;
    }
    p.vt = target;
    p.jp = 0;
    if (p.sep > 2 * SIM.slop) { p.jn = 0; p.jt = 0; }
  }
  m.vnMin = vnMin;
  for (let i = 0; i < n; i++) {
    const p = P[i];
    const Px = p.jn * nx + p.jt * tx, Py = p.jn * ny + p.jt * ty;
    A.vx -= imA * Px; A.vy -= imA * Py; A.w -= iIA * (p.rax * Py - p.ray * Px);
    B.vx += imB * Px; B.vy += imB * Py; B.w += iIB * (p.rbx * Py - p.rby * Px);
  }
}

function solveVelocity(m) {
  const A = m.a, B = m.b, imA = A.im, iIA = A.iI, imB = B.im, iIB = B.iI;
  const nx = m.nx, ny = m.ny, tx = ny, ty = -nx, mu = m.mu, n = m.count, P = m.p;
  let vAx = A.vx, vAy = A.vy, wA = A.w, vBx = B.vx, vBy = B.vy, wB = B.w;
  for (let i = 0; i < n; i++) {
    const p = P[i];
    const dvx = vBx - wB * p.rby - vAx + wA * p.ray;
    const dvy = vBy + wB * p.rbx - vAy - wA * p.rax;
    const vt = dvx * tx + dvy * ty;
    const maxF = mu * p.jn;
    const nj = clamp(p.jt - p.mt * vt, -maxF, maxF);
    const lam = nj - p.jt; p.jt = nj;
    const Px = lam * tx, Py = lam * ty;
    vAx -= imA * Px; vAy -= imA * Py; wA -= iIA * (p.rax * Py - p.ray * Px);
    vBx += imB * Px; vBy += imB * Py; wB += iIB * (p.rbx * Py - p.rby * Px);
  }
  for (let i = 0; i < n; i++) {
    const p = P[i];
    const dvx = vBx - wB * p.rby - vAx + wA * p.ray;
    const dvy = vBy + wB * p.rbx - vAy - wA * p.rax;
    const vn = dvx * nx + dvy * ny;
    const nj = Math.max(p.jn + p.mn * (p.vt - vn), 0);
    const lam = nj - p.jn; p.jn = nj;
    const Px = lam * nx, Py = lam * ny;
    vAx -= imA * Px; vAy -= imA * Py; wA -= iIA * (p.rax * Py - p.ray * Px);
    vBx += imB * Px; vBy += imB * Py; wB += iIB * (p.rbx * Py - p.rby * Px);
  }
  A.vx = vAx; A.vy = vAy; A.w = wA; B.vx = vBx; B.vy = vBy; B.w = wB;
}

// Split impulse: penetration is removed through pseudo velocities that never
// feed back into real momentum, so overlap recovery cannot launch bricks.
function solvePosition(m, invH) {
  const A = m.a, B = m.b, imA = A.im, iIA = A.iI, imB = B.im, iIB = B.iI;
  const nx = m.nx, ny = m.ny, n = m.count, P = m.p;
  for (let i = 0; i < n; i++) {
    const p = P[i];
    let target;
    if (p.sep > 0) target = -p.sep * invH;
    else if (p.sep < -SIM.slop) target = SIM.beta * Math.min(-(p.sep + SIM.slop), SIM.maxCorrection) * invH;
    else target = 0;
    const dvx = B.pvx - B.pw * p.rby - A.pvx + A.pw * p.ray;
    const dvy = B.pvy + B.pw * p.rbx - A.pvy - A.pw * p.rax;
    const vn = dvx * nx + dvy * ny;
    const nj = Math.max(p.jp + p.mn * (target - vn), 0);
    const lam = nj - p.jp; p.jp = nj;
    const Px = lam * nx, Py = lam * ny;
    A.pvx -= imA * Px; A.pvy -= imA * Py; A.pw -= iIA * (p.rax * Py - p.ray * Px);
    B.pvx += imB * Px; B.pvy += imB * Py; B.pw += iIB * (p.rbx * Py - p.rby * Px);
  }
}

function sortByKey(L) {
  for (let i = 0; i < L.length; i++) { const b = L[i]; b.key = b.minX - b.ext; }
  for (let i = 1; i < L.length; i++) {
    const b = L[i], k = b.key;
    let j = i - 1;
    while (j >= 0 && L[j].key > k) { L[j + 1] = L[j]; j--; }
    L[j + 1] = b;
  }
}

/* ---------- world ---------- */

class World {
  constructor(settings) {
    this.gravity = settings.gravity;
    this.groundFriction = settings.groundFriction;
    this.bodies = [];
    this.bricks = [];
    this.layers = [];
    for (let k = 0; k < settings.layers; k++) this.layers.push([]);
    this.car = null;
    this.wheelsLocked = false;
    this.manifolds = new Map();
    this.active = [];
    this.stamp = 0;
    this.nextShapeId = 1;
    this.ground = new Body('ground');
    this.ground.isStatic = true;
    this.groundShape = { id: 0, body: this.ground, kind: 'ground', friction: settings.groundFriction, restitution: 0 };
    this.events = [];
    this.carTouch = false;
    this.wheelContact = [false, false];
  }

  add(body) {
    body.index = this.bodies.length;
    this.bodies.push(body);
    for (const sh of body.shapes) sh.id = this.nextShapeId++;
    body.sync();
    body.x0 = body.x; body.y0 = body.y; body.a0 = body.a;
    body.px = body.x; body.py = body.y; body.pa = body.a;
    if (body.kind === 'brick') { this.bricks.push(body); this.layers[body.layer].push(body); }
    if (body.kind === 'car') this.car = body;
    return body;
  }

  touch(sa, sb, stamp) {
    const key = sa.id * 8192 + sb.id;
    let m = this.manifolds.get(key);
    if (!m) { m = new Manifold(sa, sb); this.manifolds.set(key, m); }
    m.update(stamp);
    this.active.push(m);
    return m;
  }

  collide() {
    const stamp = ++this.stamp;
    const base = SIM.specBase;
    this.active.length = 0;
    this.carTouch = false;
    this.wheelContact[0] = this.wheelContact[1] = false;

    // Ground (static half-plane).
    for (let i = 0; i < this.bodies.length; i++) {
      const b = this.bodies[i];
      if (b.sleeping) continue;
      const margin = base + b.ext;
      if (b.minY > margin) continue;
      for (let s = 0; s < b.shapes.length; s++) {
        const sh = b.shapes[s];
        if (sh.minY > margin) continue;
        collideGround(sh, margin);
        if (CP.n) {
          this.touch(this.groundShape, sh, stamp);
          if (sh.wheelIndex >= 0 && CP.minSep < 0.01) this.wheelContact[sh.wheelIndex] = true;
        }
      }
    }

    // Bricks, per depth layer (layers are separate wythes and do not touch each other).
    for (let l = 0; l < this.layers.length; l++) {
      const L = this.layers[l];
      sortByKey(L);
      const n = L.length;
      for (let i = 0; i < n; i++) {
        const a = L[i];
        const aMax = a.maxX + a.ext;
        for (let j = i + 1; j < n; j++) {
          const b = L[j];
          if (b.key > aMax) break;
          if (a.sleeping && b.sleeping) continue;
          if (a.minY - a.ext > b.maxY + b.ext || b.minY - b.ext > a.maxY + a.ext) continue;
          let sa = a.shapes[0], sb = b.shapes[0];
          if (sa.id > sb.id) { const t = sa; sa = sb; sb = t; }
          collidePolys(sa, sb, base + a.ext + b.ext);
          if (CP.n) this.touch(sa, sb, stamp);
        }
      }
    }

    // Car against every brick in every layer (the car spans the full wall depth).
    const car = this.car;
    if (car) {
      for (let i = 0; i < this.bricks.length; i++) {
        const b = this.bricks[i];
        if (car.sleeping && b.sleeping) continue;
        const ext = car.ext + b.ext;
        if (b.minX > car.maxX + ext || b.maxX < car.minX - ext || b.minY > car.maxY + ext || b.maxY < car.minY - ext) continue;
        const bs = b.shapes[0];
        for (let s = 0; s < car.shapes.length; s++) {
          const cs = car.shapes[s];
          if (b.minX > cs.maxX + ext || b.maxX < cs.minX - ext || b.minY > cs.maxY + ext || b.maxY < cs.minY - ext) continue;
          collidePolys(cs, bs, base + ext);
          if (CP.n) {
            this.touch(cs, bs, stamp);
            if (CP.minSep < 0.01) this.carTouch = true;
          }
        }
      }
    }

    // Drop manifolds that were not refreshed, unless both sides are at rest
    // (kept so a woken brick restarts with its resting impulses).
    for (const [key, m] of this.manifolds) {
      if (m.stamp === stamp) continue;
      if ((m.a.sleeping || m.a.isStatic) && (m.b.sleeping || m.b.isStatic)) continue;
      this.manifolds.delete(key);
    }
  }

  wakeTouching() {
    const w2 = SIM.wakeSpeed * SIM.wakeSpeed;
    for (let i = 0; i < this.active.length; i++) {
      const m = this.active[i], A = m.a, B = m.b;
      if (A.sleeping && !B.sleeping && !B.isStatic && B.motion2 > w2) A.wake();
      else if (B.sleeping && !A.sleeping && !A.isStatic && A.motion2 > w2) B.wake();
    }
  }

  substep(h) {
    const invH = 1 / h, g = this.gravity, bodies = this.bodies;
    const ld = 1 / (1 + h * SIM.linDamp), ad = 1 / (1 + h * SIM.angDamp);

    for (let i = 0; i < bodies.length; i++) {
      const b = bodies[i];
      if (b.sleeping) { b.im = 0; b.iI = 0; b.ext = 0; continue; }
      b.im = b.invMass; b.iI = b.invI;
      b.vx = (b.vx + b.fx * b.invMass * h) * ld;
      b.vy = (b.vy + (b.fy * b.invMass - g) * h) * ld;
      b.w *= ad;
      b.pvx = 0; b.pvy = 0; b.pw = 0;
      const sp = Math.sqrt(b.vx * b.vx + b.vy * b.vy) + Math.abs(b.w) * b.radius;
      b.ext = Math.min(SIM.maxExt, 0.004 + sp * h * 1.25);
    }

    this.collide();
    this.wakeTouching();

    const act = this.active, nA = act.length;
    const lockedMu = this.groundFriction;
    for (let i = 0; i < nA; i++) {
      const m = act[i];
      if (m.wheelGround) m.mu = this.wheelsLocked ? lockedMu : SIM.rollingMu;
      prestep(m, invH);
    }
    for (let it = 0; it < SIM.velIters; it++) for (let i = 0; i < nA; i++) solveVelocity(act[i]);
    for (let it = 0; it < SIM.posIters; it++) for (let i = 0; i < nA; i++) solvePosition(act[i], invH);

