  }

  // Solve the resting wall once at build time so the first woken bricks start
  // with equilibrium contact impulses instead of sagging. Positions do not move.
  prestress(h, rounds) {
    const invH = 1 / h;
    for (const b of this.bodies) { b.sleeping = false; b.im = b.invMass; b.iI = b.invI; b.ext = 0; }
    this.collide();
    const act = this.active;
    for (let r = 0; r < rounds; r++) {
      for (const b of this.bodies) { if (b.isStatic) continue; b.vx = 0; b.w = 0; b.vy = -this.gravity * h; }
      for (let i = 0; i < act.length; i++) {
        const m = act[i];
        if (m.wheelGround) m.mu = SIM.rollingMu;
        prestep(m, invH);
      }
      for (let it = 0; it < SIM.velIters; it++) for (let i = 0; i < act.length; i++) solveVelocity(act[i]);
    }
    for (const b of this.bodies) {
      if (b.isStatic) continue;
      b.vx = 0; b.vy = 0; b.w = 0; b.motion2 = 0;
      if (b.kind === 'brick') { b.sleeping = true; b.im = 0; b.iI = 0; }
    }
    this.events.length = 0;
  }
}

