+
+// Split impulse: penetration is removed through pseudo velocities that never
+// feed back into real momentum, so overlap recovery cannot launch bricks.
+function solvePosition(m, invH) {
+  const A = m.a, B = m.b, imA = A.im, iIA = A.iI, imB = B.im, iIB = B.iI;
+  const nx = m.nx, ny = m.ny, n = m.count, P = m.p;
