+    if (p.sep > 0) target = -p.sep * invH;
+    else if (p.sep < -SIM.slop) target = SIM.beta * Math.min(-(p.sep + SIM.slop), SIM.maxCorrection) * invH;
+    else target = 0;
+    const dvx = B.pvx - B.pw * p.rby - A.pvx + A.pw * p.ray;
+    const dvy = B.pvy + B.pw * p.rbx - A.pvy - A.pw * p.rax;
+    const vn = dvx * nx + dvy * ny;
+    const nj = Math.max(p.jp + p.mn * (target - vn), 0);
+    const lam = nj - p.jp; p.jp = nj;
+    const Px = lam * nx, Py = lam * ny;
+    A.pvx -= imA * Px; A.pvy -= imA * Py; A.pw -= iIA * (p.rax * Py - p.ray * Px);
+    B.pvx += imB * Px; B.pvy += imB * Py; B.pw += iIB * (p.rbx * Py - p.rby * Px);
+  }
+}
