+function sortByKey(L) {
+  for (let i = 0; i < L.length; i++) { const b = L[i]; b.key = b.minX - b.ext; }
+  for (let i = 1; i < L.length; i++) {
+    const b = L[i], k = b.key;
+    let j = i - 1;
+    while (j >= 0 && L[j].key > k) { L[j + 1] = L[j]; j--; }
+    L[j + 1] = b;
+  }
+}
