+/* ---------- world ---------- */
+
+class World {
+  constructor(settings) {
+    this.gravity = settings.gravity;
+    this.groundFriction = settings.groundFriction;
+    this.bodies = [];
+    this.bricks = [];
+    this.layers = [];
+    for (let k = 0; k < settings.layers; k++) this.layers.push([]);
+    this.car = null;
+    this.wheelsLocked = false;
+    this.manifolds = new Map();
+    this.active = [];
+    this.stamp = 0;
+    this.nextShapeId = 1;
+    this.ground = new Body('ground');
+    this.ground.isStatic = true;
+    this.groundShape = { id: 0, body: this.ground, kind: 'ground', friction: settings.groundFriction, restitution: 0 };
+    this.events = [];
+    this.carTouch = false;
+    this.wheelContact = [false, false];
+  }
+
+  add(body) {
+    body.index = this.bodies.length;
+    this.bodies.push(body);
+    for (const sh of body.shapes) sh.id = this.nextShapeId++;
+    body.sync();
+    body.x0 = body.x; body.y0 = body.y; body.a0 = body.a;
+    body.px = body.x; body.py = body.y; body.pa = body.a;
+    if (body.kind === 'brick') { this.bricks.push(body); this.layers[body.layer].push(body); }
+    if (body.kind === 'car') this.car = body;
+    return body;
+  }
+
+  touch(sa, sb, stamp) {
+    const key = sa.id * 8192 + sb.id;
+    let m = this.manifolds.get(key);
+    if (!m) { m = new Manifold(sa, sb); this.manifolds.set(key, m); }
+    m.update(stamp);
+    this.active.push(m);
+    return m;
+  }
+
+  collide() {
+    const stamp = ++this.stamp;
+    const base = SIM.specBase;
+    this.active.length = 0;
+    this.carTouch = false;
+    this.wheelContact[0] = this.wheelContact[1] = false;
+
+    // Ground (static half-plane).
+    for (let i = 0; i < this.bodies.length; i++) {
+      const b = this.bodies[i];
+      if (b.sleeping) continue;
+      const margin = base + b.ext;
+      if (b.minY > margin) continue;
+      for (let s = 0; s < b.shapes.length; s++) {
+        const sh = b.shapes[s];
+        if (sh.minY > margin) continue;
+        collideGround(sh, margin);
+        if (CP.n) {
+          this.touch(this.groundShape, sh, stamp);
+          if (sh.wheelIndex >= 0 && CP.minSep < 0.01) this.wheelContact[sh.wheelIndex] = true;
+        }
+      }
+    }
+
+    // Bricks, per depth layer (layers are separate wythes and do not touch each other).
+    for (let l = 0; l < this.layers.length; l++) {
+      const L = this.layers[l];
+      sortByKey(L);
+      const n = L.length;
+      for (let i = 0; i < n; i++) {
+        const a = L[i];
+        const aMax = a.maxX + a.ext;
+        for (let j = i + 1; j < n; j++) {
+          const b = L[j];
+          if (b.key > aMax) break;
+          if (a.sleeping && b.sleeping) continue;
+          if (a.minY - a.ext > b.maxY + b.ext || b.minY - b.ext > a.maxY + a.ext) continue;
+          let sa = a.shapes[0], sb = b.shapes[0];
+          if (sa.id > sb.id) { const t = sa; sa = sb; sb = t; }
+          collidePolys(sa, sb, base + a.ext + b.ext);
+          if (CP.n) this.touch(sa, sb, stamp);
+        }
+      }
+    }
+
+    // Car against every brick in every layer (the car spans the full wall depth).
+    const car = this.car;
+    if (car) {
+      for (let i = 0; i < this.bricks.length; i++) {
+        const b = this.bricks[i];
+        if (car.sleeping && b.sleeping) continue;
+        const ext = car.ext + b.ext;
+        if (b.minX > car.maxX + ext || b.maxX < car.minX - ext || b.minY > car.maxY + ext || b.maxY < car.minY - ext) continue;
+        const bs = b.shapes[0];
+        for (let s = 0; s < car.shapes.length; s++) {
+          const cs = car.shapes[s];
+          if (b.minX > cs.maxX + ext || b.maxX < cs.minX - ext || b.minY > cs.maxY + ext || b.maxY < cs.minY - ext) continue;
+          collidePolys(cs, bs, base + ext);
+          if (CP.n) {
+            this.touch(cs, bs, stamp);
+            if (CP.minSep < 0.01) this.carTouch = true;
+          }
+        }
+      }
+    }
+
+    // Drop manifolds that were not refreshed, unless both sides are at rest
+    // (kept so a woken brick restarts with its resting impulses).
+    for (const [key, m] of this.manifolds) {
+      if (m.stamp === stamp) continue;
+      if ((m.a.sleeping || m.a.isStatic) && (m.b.sleeping || m.b.isStatic)) continue;
+      this.manifolds.delete(key);
+    }
+  }
+
+  wakeTouching() {
+    const w2 = SIM.wakeSpeed * SIM.wakeSpeed;
+    for (let i = 0; i < this.active.length; i++) {
+      const m = this.active[i], A = m.a, B = m.b;
+      if (A.sleeping && !B.sleeping && !B.isStatic && B.motion2 > w2) A.wake();
+      else if (B.sleeping && !A.sleeping && !A.isStatic && A.motion2 > w2) B.wake();
+    }
+  }
+
+  substep(h) {
+    const invH = 1 / h, g = this.gravity, bodies = this.bodies;
+    const ld = 1 / (1 + h * SIM.linDamp), ad = 1 / (1 + h * SIM.angDamp);
+
+    for (let i = 0; i < bodies.length; i++) {
+      const b = bodies[i];
+      if (b.sleeping) { b.im = 0; b.iI = 0; b.ext = 0; continue; }
+      b.im = b.invMass; b.iI = b.invI;
+      b.vx = (b.vx + b.fx * b.invMass * h) * ld;
+      b.vy = (b.vy + (b.fy * b.invMass - g) * h) * ld;
+      b.w *= ad;
+      b.pvx = 0; b.pvy = 0; b.pw = 0;
+      const sp = Math.sqrt(b.vx * b.vx + b.vy * b.vy) + Math.abs(b.w) * b.radius;
+      b.ext = Math.min(SIM.maxExt, 0.004 + sp * h * 1.25);
+    }
+
+    this.collide();
+    this.wakeTouching();
+
+    const act = this.active, nA = act.length;
+    const lockedMu = this.groundFriction;
+    for (let i = 0; i < nA; i++) {
+      const m = act[i];
+      if (m.wheelGround) m.mu = this.wheelsLocked ? lockedMu : SIM.rollingMu;
+      prestep(m, invH);
+    }
+    for (let it = 0; it < SIM.velIters; it++) for (let i = 0; i < nA; i++) solveVelocity(act[i]);
+    for (let it = 0; it < SIM.posIters; it++) for (let i = 0; i < nA; i++) solvePosition(act[i], invH);
+
+    for (let i = 0; i < nA; i++) {
+      const m = act[i];
+      if (m.vnMin < -2.5 && this.events.length < 96) {
+        const p = m.p[0];
+        this.events.push({ x: p.x, y: p.y, s: -m.vnMin, k: m.kind, nx: m.nx, ny: m.ny });
+      }
+    }
+
+    const vMax2 = SIM.maxV * SIM.maxV;
+    const sl2 = SIM.sleepLin * SIM.sleepLin, sa2 = SIM.sleepAng * SIM.sleepAng;
+    for (let i = 0; i < bodies.length; i++) {
+      const b = bodies[i];
+      if (b.sleeping || b.isStatic) continue;
+      let v2 = b.vx * b.vx + b.vy * b.vy;
+      if (v2 > vMax2) { const k = SIM.maxV / Math.sqrt(v2); b.vx *= k; b.vy *= k; v2 = vMax2; }
+      b.w = clamp(b.w, -SIM.maxW, SIM.maxW);
+      b.x += (b.vx + b.pvx) * h;
+      b.y += (b.vy + b.pvy) * h;
+      b.a += (b.w + b.pw) * h;
+      b.sync();
+      const w2 = b.w * b.w;
+      b.motion2 = v2 + w2 * b.radius * b.radius;
+      if (b.canSleep && v2 < sl2 && w2 < sa2) {
+        b.sleepTimer += h;
+        if (b.sleepTimer >= SIM.sleepTime) {
+          b.sleeping = true; b.vx = 0; b.vy = 0; b.w = 0; b.im = 0; b.iI = 0; b.motion2 = 0;
+        }
+      } else {
+        b.sleepTimer = 0;
+      }
+    }
+  }
+
+  // Solve the resting wall once at build time so the first woken bricks start
+  // with equilibrium contact impulses instead of sagging. Positions do not move.
+  prestress(h, rounds) {
+    const invH = 1 / h;
+    for (const b of this.bodies) { b.sleeping = false; b.im = b.invMass; b.iI = b.invI; b.ext = 0; }
+    this.collide();
+    const act = this.active;
+    for (let r = 0; r < rounds; r++) {
+      for (const b of this.bodies) { if (b.isStatic) continue; b.vx = 0; b.w = 0; b.vy = -this.gravity * h; }
+      for (let i = 0; i < act.length; i++) {
+        const m = act[i];
+        if (m.wheelGround) m.mu = SIM.rollingMu;
+        prestep(m, invH);
+      }
+      for (let it = 0; it < SIM.velIters; it++) for (let i = 0; i < act.length; i++) solveVelocity(act[i]);
+    }
+    for (const b of this.bodies) {
+      if (b.isStatic) continue;
+      b.vx = 0; b.vy = 0; b.w = 0; b.motion2 = 0;
+      if (b.kind === 'brick') { b.sleeping = true; b.im = 0; b.iI = 0; }
+    }
+    this.events.length = 0;
+  }
+}
+
+/*__EXPERIMENT__*/
 </script>
 </body>
 </html>

