/* =====================================================================
   4. SCENE CONSTRUCTION
   Design coordinates for the car: x = 0 at mid-length, y = 0 at the road,
   front bumper at +2.10 m, roof at 1.45 m.
   ===================================================================== */

const CAR_DESIGN = Object.freeze({
  lower: [[-1.70, 0.20], [1.75, 0.20], [2.10, 0.32], [2.10, 0.72], [1.75, 0.92], [-1.95, 0.95], [-2.10, 0.75], [-2.10, 0.32]],
  cabin: [[-1.80, 0.93], [1.05, 0.91], [0.15, 1.45], [-1.05, 1.45]],
  wheelR: 0.33,
  wheelX: [-1.35, 1.40],
  wheelSides: 12,
  massFrac: { lower: 0.74, cabin: 0.14, wheel: 0.06 },
  crushPivot: 1.5,   // crumple zone starts here and extends to the bumper
  front: 2.10,
});
const WHEEL_AP = CAR_DESIGN.wheelR * Math.cos(Math.PI / CAR_DESIGN.wheelSides);

function wheelVerts(cx) {
  const { wheelR: r, wheelSides: n } = CAR_DESIGN;
  const out = [];
  for (let k = 0; k < n; k++) {
    const t = -Math.PI / 2 - Math.PI / n + (k * 2 * Math.PI) / n;
    out.push([cx + r * Math.cos(t), WHEEL_AP + r * Math.sin(t)]);
  }
  return out;
}

// Maps a design x coordinate into the crushed front end (identity behind the pivot).
function crushX(x, c) {
  const p = CAR_DESIGN.crushPivot, f = CAR_DESIGN.front;
  return x <= p ? x : p + ((x - p) * (f - p - c)) / (f - p);
}

function buildCar(world, s) {
  const D = CAR_DESIGN;
  const body = { kind: 'carBody', friction: SIM.carBodyMu, restitution: SIM.carRestitution };
  const parts = [
    { verts: D.lower, frac: D.massFrac.lower, props: body },
    { verts: D.cabin, frac: D.massFrac.cabin, props: body },
    { verts: wheelVerts(D.wheelX[0]), frac: D.massFrac.wheel, props: { kind: 'wheel', friction: SIM.wheelMu, restitution: SIM.carRestitution, wheelIndex: 0 } },
    { verts: wheelVerts(D.wheelX[1]), frac: D.massFrac.wheel, props: { kind: 'wheel', friction: SIM.wheelMu, restitution: SIM.carRestitution, wheelIndex: 1 } },
  ];
  const M = s.carMass;
  let cx = 0, cy = 0;
  const md = parts.map((p) => {
    const d = polygonMassData(p.verts);
    const m = p.frac * M;
    cx += m * d.cx; cy += m * d.cy;
    return { d, m };
  });
  cx /= M; cy /= M;
  let I = 0;
  for (const { d, m } of md) I += (m * d.Iunit) / d.area + m * ((d.cx - cx) ** 2 + (d.cy - cy) ** 2);

  const car = new Body('car');
  car.com = { x: cx, y: cy };
  for (const p of parts) car.addShape(new Shape(p.verts.map(([x, y]) => [x - cx, y - cy]), p.props));
  car.setMass(M, I);
  car.x = SIM.wallX - SIM.runup - D.front + cx;
  car.y = cy + 0.0005;
  car.canSleep = false;
  world.add(car);
  return car;
}

function setCrush(car, c) {
  const verts = CAR_DESIGN.lower.map(([x, y], i) => [(i >= 1 && i <= 4 ? crushX(x, c) : x) - car.com.x, y - car.com.y]);
  car.shapes[0].setLocal(verts);
  car.sync();
}

// Design point -> world point for the car body.
function carPoint(car, dx, dy, out) {
  const lx = dx - car.com.x, ly = dy - car.com.y;
  out[0] = car.x + car.c * lx - car.s * ly;
  out[1] = car.y + car.s * lx + car.c * ly;
  return out;
}

// Freestanding dry-stacked wall in running bond. Rows alternate between full
// bricks and a half-bat start so vertical joints are staggered by half a brick
// and both ends stay flush. Each depth layer flips the bond parity.
function buildWall(world, s) {
  const bw = FIXED.brickW, bh = FIXED.brickH;
  const props = { kind: 'brick', friction: s.brickFriction, restitution: s.brickRestitution };
  let serial = 0;
  const add = (layer, row, x, w, m) => {
    const b = new Body('brick');
    const hw = w / 2, hh = bh / 2;
    b.layer = layer; b.row = row; b.half = w < bw;
    b.hw = hw; b.hh = hh;
    b.addShape(new Shape([[-hw, -hh], [hw, -hh], [hw, hh], [-hw, hh]], props));
    b.setMass(m, (m * (w * w + bh * bh)) / 12);
    b.x = SIM.wallX + x;
    b.y = bh * (row + 0.5);
    b.shade = hash32(serial++ * 31 + layer * 7) % 6;
    world.add(b);
  };
  for (let k = 0; k < s.layers; k++) {
    for (let r = 0; r < s.rows; r++) {
      if (((r + k) & 1) === 0) {
        for (let c = 0; c < s.cols; c++) add(k, r, bw * (c + 0.5), bw, s.brickMass);
      } else {
        add(k, r, bw / 4, bw / 2, s.brickMass / 2);
        for (let c = 0; c < s.cols - 1; c++) add(k, r, bw * (c + 1), bw, s.brickMass);
        add(k, r, s.cols * bw - bw / 4, bw / 2, s.brickMass / 2);
      }
    }
  }
}

/* =====================================================================
   5. EXPERIMENT CONTROLLER
   Owns one world, drives the tow launch, detects impact, tracks telemetry.
   The physical result depends only on the settings and the fixed step.
   ===================================================================== */

class Experiment {
  constructor(settings) {
    this.settings = Object.freeze({ ...settings });
    const w = (this.world = new World(this.settings));
    this.car = buildCar(w, this.settings);
    buildWall(w, this.settings);
    w.prestress(SIM.frameDt / SIM.substeps, 40);

    this.pieces = w.bricks.length;
    this.wallMass = w.bricks.reduce((sum, b) => sum + b.mass, 0);
    this.wallEnd = SIM.wallX + this.settings.cols * FIXED.brickW;
    this.state = 'ready';
    this.t = 0;
    this.frame = 0;
    // Tow sled: constant acceleration reaching the set speed cruiseLead metres before the wall.
    this.launchA = Math.max(this.settings.carSpeed ** 2 / (2 * (SIM.runup - SIM.cruiseLead)), 1.5);
    this.impactT = null;
    this.impactSpeed = null;
    this.impactKE = 0;
    this.peakDecel = 0;
    this.slide = 0;
    this.crush = 0;
    this.settleTimer = 0;
    this.minVxAfter = 0;
    this.maxFront = -Infinity;
    this.moving = 0;
    this.displaced = 0;
    this.history = [];
    this.skids = [[], []];
    this.skidOpen = [null, null];
    this.touchFrame = false;
    this.impactFrame = false;
    this._pt = [0, 0];
  }

  get running() { return this.state === 'launch' || this.state === 'impact'; }

  start() { if (this.state === 'ready') this.state = 'launch'; }

  carFrontX() {
    return carPoint(this.car, CAR_DESIGN.front - this.crush, 0.52, this._pt)[0];
  }

  wheelCenter(i, out) {
    return carPoint(this.car, CAR_DESIGN.wheelX[i], WHEEL_AP, out);
  }

  snapshot() {
    const bodies = this.world.bodies;
    for (let i = 0; i < bodies.length; i++) { const b = bodies[i]; b.px = b.x; b.py = b.y; b.pa = b.a; }
  }

  stepFrame() {
    if (!this.running) return;
    const w = this.world, car = this.car, s = this.settings;
    const h = SIM.frameDt / SIM.substeps;
    w.events.length = 0;
    this.touchFrame = false;
    this.impactFrame = false;
    const vxStart = car.vx;

    for (let i = 0; i < SIM.substeps; i++) {
      if (this.state === 'launch') {
        const vDes = Math.min(s.carSpeed, this.launchA * (this.t + h));
        car.fx = clamp((car.mass * (vDes - car.vx)) / h, 0, car.mass * (this.launchA * 3 + 30));
      } else {
        car.fx = 0;
      }
      const vBefore = car.vx;
      w.substep(h);
      this.t += h;
      if (w.carTouch) this.touchFrame = true;
      if (this.state === 'launch' && w.carTouch) {
        this.state = 'impact';
        this.impactT = this.t;
        this.impactSpeed = vBefore;
        this.impactKE = 0.5 * car.mass * vBefore * vBefore;
        this.impactFrame = true;
        car.fx = 0;
        w.wheelsLocked = true;   // brakes lock on impact
      }
      if (w.wheelsLocked && (w.wheelContact[0] || w.wheelContact[1])) this.slide += Math.abs(car.vx) * h;
    }
    this.frame++;

    if (this.impactT !== null) {
      const decel = -(car.vx - vxStart) / SIM.frameDt / G0;
      if (decel > this.peakDecel) this.peakDecel = decel;
      if (this.touchFrame) {
        // Plastic crumple: grows with the kinetic energy the car has lost to the wall.
        const ke = 0.5 * car.mass * (car.vx * car.vx + car.vy * car.vy) + 0.5 * car.I * car.w * car.w;
        const E = this.impactKE - ke - s.groundFriction * car.mass * s.gravity * this.slide;
        const target = SIM.crushMax * (1 - Math.exp(-Math.max(0, E) / SIM.crushE0));
        if (target > this.crush + 0.002) { this.crush = target; setCrush(car, target); }
      }
      this.minVxAfter = Math.min(this.minVxAfter, car.vx);
      this.maxFront = Math.max(this.maxFront, this.carFrontX());
      if (this.t - this.impactT > 0.4) car.canSleep = true;
    }

    this.updateSkids();

    let moving = 0;
    const bricks = w.bricks;
    for (let i = 0; i < bricks.length; i++) { const b = bricks[i]; if (!b.sleeping && b.motion2 > 0.0025) moving++; }
    this.moving = moving;
    if (this.frame % 6 === 0) this.countDisplaced();

    const speed = Math.hypot(car.vx, car.vy);
    this.history.push(speed);

    if (this.state === 'impact') {
      if (moving === 0 && speed < 0.05) this.settleTimer += SIM.frameDt;
      else this.settleTimer = 0;
      if (this.settleTimer >= SIM.settleTime || this.t >= SIM.maxTime) this.finish();
    } else if (this.state === 'launch' && this.t > 15) {
      this.finish();
    }
  }

  finish() {
    this.state = 'settled';
    this.car.fx = 0;
    this.countDisplaced();
  }

  countDisplaced() {
    let n = 0;
    const bricks = this.world.bricks;
    for (let i = 0; i < bricks.length; i++) {
      const b = bricks[i];
      const dx = b.x - b.x0, dy = b.y - b.y0;
      if (dx * dx + dy * dy > 0.0036 || Math.abs(b.a - b.a0) > 0.1) n++;
    }
    this.displaced = n;
  }

  updateSkids() {
    const w = this.world, car = this.car;
    for (let i = 0; i < 2; i++) {
      const sliding = w.wheelsLocked && w.wheelContact[i] && Math.abs(car.vx) > 0.15;
      if (!sliding) { this.skidOpen[i] = null; continue; }
      const x = this.wheelCenter(i, this._pt)[0];
      if (!this.skidOpen[i]) { const seg = [x, x]; this.skids[i].push(seg); this.skidOpen[i] = seg; }
      else this.skidOpen[i][1] = x;
    }
  }

  stateHash() {
    let h = 2166136261;
    const mix = (v) => { h ^= Math.round(v * 1e6) | 0; h = Math.imul(h, 16777619); };
    for (const b of this.world.bodies) { mix(b.x); mix(b.y); mix(b.a); mix(b.vx); mix(b.vy); }
    return (h >>> 0).toString(16).padStart(8, '0');
  }

  verdict() {
    if (this.impactT === null) return '';
    const f = this.displaced / this.pieces;
    const past = this.maxFront - SIM.wallX;
    let head;
    if (this.maxFront > this.wallEnd + 0.3) head = 'Car broke through the whole wall';
    else if (f > 0.5) head = 'Wall collapsed';
    else if (f > 0.04) head = 'Partial collapse';
    else head = 'Wall held';
    const parts = [
      `<b>${head}.</b> ${this.displaced} of ${this.pieces} pieces displaced (${Math.round(f * 100)}%)`,
      `car front reached ${past.toFixed(2)} m past the wall face`,
      `peak decel. ${this.peakDecel.toFixed(1)} g`,
    ];
    if (this.minVxAfter < -0.2) parts.push(`recoil ${(-this.minVxAfter).toFixed(1)} m/s`);
    return parts.join(' &middot; ');
  }

  summary() {
    const car = this.car;
    return {
      state: this.state,
      t: +this.t.toFixed(4),
      impactT: this.impactT === null ? null : +this.impactT.toFixed(4),
      impactSpeed: this.impactSpeed === null ? null : +this.impactSpeed.toFixed(3),
      carX: +car.x.toFixed(4),
      carVx: +car.vx.toFixed(4),
      carAngleDeg: +((car.a * 180) / Math.PI).toFixed(2),
      maxFrontPastWall: this.maxFront === -Infinity ? null : +(this.maxFront - SIM.wallX).toFixed(3),
      peakDecelG: +this.peakDecel.toFixed(2),
      crush: +this.crush.toFixed(3),
      pieces: this.pieces,
      displaced: this.displaced,
      moving: this.moving,
      minBrickY: +Math.min(...this.world.bricks.map((b) => b.minY)).toFixed(4),
      hash: this.stateHash(),
    };
  }
}

/*__RENDER__*/

/* =====================================================================
   4. SCENE CONSTRUCTION
   Design coordinates for the car: x = 0 at mid-length, y = 0 at the road,
   front bumper at +2.10 m, roof at 1.45 m.
   ===================================================================== */

const CAR_DESIGN = Object.freeze({
  lower: [[-1.70, 0.20], [1.75, 0.20], [2.10, 0.32], [2.10, 0.72], [1.75, 0.92], [-1.95, 0.95], [-2.10, 0.75], [-2.10, 0.32]],
  cabin: [[-1.80, 0.93], [1.05, 0.91], [0.15, 1.45], [-1.05, 1.45]],
  wheelR: 0.33,
  wheelX: [-1.35, 1.40],
  wheelSides: 12,
  massFrac: { lower: 0.74, cabin: 0.14, wheel: 0.06 },
  crushPivot: 1.5,   // crumple zone starts here and extends to the bumper
  front: 2.10,
});
const WHEEL_AP = CAR_DESIGN.wheelR * Math.cos(Math.PI / CAR_DESIGN.wheelSides);

function wheelVerts(cx) {
  const { wheelR: r, wheelSides: n } = CAR_DESIGN;
  const out = [];
  for (let k = 0; k < n; k++) {
    const t = -Math.PI / 2 - Math.PI / n + (k * 2 * Math.PI) / n;
    out.push([cx + r * Math.cos(t), WHEEL_AP + r * Math.sin(t)]);
  }
  return out;
}

// Maps a design x coordinate into the crushed front end (identity behind the pivot).
function crushX(x, c) {
  const p = CAR_DESIGN.crushPivot, f = CAR_DESIGN.front;
  return x <= p ? x : p + ((x - p) * (f - p - c)) / (f - p);
}

function buildCar(world, s) {
  const D = CAR_DESIGN;
  const body = { kind: 'carBody', friction: SIM.carBodyMu, restitution: SIM.carRestitution };
  const parts = [
    { verts: D.lower, frac: D.massFrac.lower, props: body },
    { verts: D.cabin, frac: D.massFrac.cabin, props: body },
    { verts: wheelVerts(D.wheelX[0]), frac: D.massFrac.wheel, props: { kind: 'wheel', friction: SIM.wheelMu, restitution: SIM.carRestitution, wheelIndex: 0 } },
    { verts: wheelVerts(D.wheelX[1]), frac: D.massFrac.wheel, props: { kind: 'wheel', friction: SIM.wheelMu, restitution: SIM.carRestitution, wheelIndex: 1 } },
  ];
  const M = s.carMass;
  let cx = 0, cy = 0;
  const md = parts.map((p) => {
    const d = polygonMassData(p.verts);
    const m = p.frac * M;
    cx += m * d.cx; cy += m * d.cy;
    return { d, m };
  });
  cx /= M; cy /= M;
  let I = 0;
  for (const { d, m } of md) I += (m * d.Iunit) / d.area + m * ((d.cx - cx) ** 2 + (d.cy - cy) ** 2);

  const car = new Body('car');
  car.com = { x: cx, y: cy };
  for (const p of parts) car.addShape(new Shape(p.verts.map(([x, y]) => [x - cx, y - cy]), p.props));
  car.setMass(M, I);
  car.x = SIM.wallX - SIM.runup - D.front + cx;
  car.y = cy + 0.0005;
  car.canSleep = false;
  world.add(car);
  return car;
}

function setCrush(car, c) {
  const verts = CAR_DESIGN.lower.map(([x, y], i) => [(i >= 1 && i <= 4 ? crushX(x, c) : x) - car.com.x, y - car.com.y]);
  car.shapes[0].setLocal(verts);
  car.sync();
}

// Design point -> world point for the car body.
function carPoint(car, dx, dy, out) {
  const lx = dx - car.com.x, ly = dy - car.com.y;
  out[0] = car.x + car.c * lx - car.s * ly;
  out[1] = car.y + car.s * lx + car.c * ly;
  return out;
}

// Freestanding dry-stacked wall in running bond. Rows alternate between full
// bricks and a half-bat start so vertical joints are staggered by half a brick
// and both ends stay flush. Each depth layer flips the bond parity.
function buildWall(world, s) {
  const bw = FIXED.brickW, bh = FIXED.brickH;
  const props = { kind: 'brick', friction: s.brickFriction, restitution: s.brickRestitution };
  let serial = 0;
  const add = (layer, row, x, w, m) => {
    const b = new Body('brick');
    const hw = w / 2, hh = bh / 2;
    b.layer = layer; b.row = row; b.half = w < bw;
    b.hw = hw; b.hh = hh;
    b.addShape(new Shape([[-hw, -hh], [hw, -hh], [hw, hh], [-hw, hh]], props));
    b.setMass(m, (m * (w * w + bh * bh)) / 12);
    b.x = SIM.wallX + x;
    b.y = bh * (row + 0.5);
    b.shade = hash32(serial++ * 31 + layer * 7) % 6;
    world.add(b);
  };
  for (let k = 0; k < s.layers; k++) {
    for (let r = 0; r < s.rows; r++) {
      if (((r + k) & 1) === 0) {
        for (let c = 0; c < s.cols; c++) add(k, r, bw * (c + 0.5), bw, s.brickMass);
      } else {
        add(k, r, bw / 4, bw / 2, s.brickMass / 2);
        for (let c = 0; c < s.cols - 1; c++) add(k, r, bw * (c + 1), bw, s.brickMass);
        add(k, r, s.cols * bw - bw / 4, bw / 2, s.brickMass / 2);
      }
    }
  }
}

/* =====================================================================
   5. EXPERIMENT CONTROLLER
   Owns one world, drives the tow launch, detects impact, tracks telemetry.
   The physical result depends only on the settings and the fixed step.
   ===================================================================== */

class Experiment {
  constructor(settings) {
    this.settings = Object.freeze({ ...settings });
    const w = (this.world = new World(this.settings));
    this.car = buildCar(w, this.settings);
    buildWall(w, this.settings);
    w.prestress(SIM.frameDt / SIM.substeps, 40);

    this.pieces = w.bricks.length;
    this.wallMass = w.bricks.reduce((sum, b) => sum + b.mass, 0);
    this.wallEnd = SIM.wallX + this.settings.cols * FIXED.brickW;
    this.state = 'ready';
    this.t = 0;
    this.frame = 0;
    // Tow sled: constant acceleration reaching the set speed cruiseLead metres before the wall.
    this.launchA = Math.max(this.settings.carSpeed ** 2 / (2 * (SIM.runup - SIM.cruiseLead)), 1.5);
    this.impactT = null;
    this.impactSpeed = null;
    this.impactKE = 0;
    this.peakDecel = 0;
    this.slide = 0;
    this.crush = 0;
    this.settleTimer = 0;
    this.minVxAfter = 0;
    this.maxFront = -Infinity;
    this.moving = 0;
    this.displaced = 0;
    this.history = [];
    this.skids = [[], []];
    this.skidOpen = [null, null];
    this.touchFrame = false;
    this.impactFrame = false;
    this._pt = [0, 0];
  }

  get running() { return this.state === 'launch' || this.state === 'impact'; }

  start() { if (this.state === 'ready') this.state = 'launch'; }

  carFrontX() {
    return carPoint(this.car, CAR_DESIGN.front - this.crush, 0.52, this._pt)[0];
  }

  wheelCenter(i, out) {
    return carPoint(this.car, CAR_DESIGN.wheelX[i], WHEEL_AP, out);
  }

  snapshot() {
    const bodies = this.world.bodies;
    for (let i = 0; i < bodies.length; i++) { const b = bodies[i]; b.px = b.x; b.py = b.y; b.pa = b.a; }
  }

  stepFrame() {
    if (!this.running) return;
    const w = this.world, car = this.car, s = this.settings;
    const h = SIM.frameDt / SIM.substeps;
    w.events.length = 0;
    this.touchFrame = false;
    this.impactFrame = false;
    const vxStart = car.vx;

    for (let i = 0; i < SIM.substeps; i++) {
      if (this.state === 'launch') {
        const vDes = Math.min(s.carSpeed, this.launchA * (this.t + h));
        car.fx = clamp((car.mass * (vDes - car.vx)) / h, 0, car.mass * (this.launchA * 3 + 30));
      } else {
        car.fx = 0;
      }
      const vBefore = car.vx;
      w.substep(h);
      this.t += h;
      if (w.carTouch) this.touchFrame = true;
      if (this.state === 'launch' && w.carTouch) {
        this.state = 'impact';
        this.impactT = this.t;
        this.impactSpeed = vBefore;
        this.impactKE = 0.5 * car.mass * vBefore * vBefore;
        this.impactFrame = true;
        car.fx = 0;
        w.wheelsLocked = true;   // brakes lock on impact
      }
      if (w.wheelsLocked && (w.wheelContact[0] || w.wheelContact[1])) this.slide += Math.abs(car.vx) * h;
    }
    this.frame++;

    if (this.impactT !== null) {
      const decel = -(car.vx - vxStart) / SIM.frameDt / G0;
      if (decel > this.peakDecel) this.peakDecel = decel;
      if (this.touchFrame) {
        // Plastic crumple: grows with the kinetic energy the car has lost to the wall.
        const ke = 0.5 * car.mass * (car.vx * car.vx + car.vy * car.vy) + 0.5 * car.I * car.w * car.w;
        const E = this.impactKE - ke - s.groundFriction * car.mass * s.gravity * this.slide;
        const target = SIM.crushMax * (1 - Math.exp(-Math.max(0, E) / SIM.crushE0));
        if (target > this.crush + 0.002) { this.crush = target; setCrush(car, target); }
      }
      this.minVxAfter = Math.min(this.minVxAfter, car.vx);
      this.maxFront = Math.max(this.maxFront, this.carFrontX());
      if (this.t - this.impactT > 0.4) car.canSleep = true;
    }

    this.updateSkids();

    let moving = 0;
    const bricks = w.bricks;
    for (let i = 0; i < bricks.length; i++) { const b = bricks[i]; if (!b.sleeping && b.motion2 > 0.0025) moving++; }
    this.moving = moving;
    if (this.frame % 6 === 0) this.countDisplaced();

    const speed = Math.hypot(car.vx, car.vy);
    this.history.push(speed);

    if (this.state === 'impact') {
      if (moving === 0 && speed < 0.05) this.settleTimer += SIM.frameDt;
      else this.settleTimer = 0;
      if (this.settleTimer >= SIM.settleTime || this.t >= SIM.maxTime) this.finish();
    } else if (this.state === 'launch' && this.t > 15) {
      this.finish();
    }
  }

  finish() {
    this.state = 'settled';
    this.car.fx = 0;
    this.countDisplaced();
  }

  countDisplaced() {
    let n = 0;
    const bricks = this.world.bricks;
    for (let i = 0; i < bricks.length; i++) {
      const b = bricks[i];
      const dx = b.x - b.x0, dy = b.y - b.y0;
      if (dx * dx + dy * dy > 0.0036 || Math.abs(b.a - b.a0) > 0.1) n++;
    }
    this.displaced = n;
  }

  updateSkids() {
    const w = this.world, car = this.car;
    for (let i = 0; i < 2; i++) {
      const sliding = w.wheelsLocked && w.wheelContact[i] && Math.abs(car.vx) > 0.15;
      if (!sliding) { this.skidOpen[i] = null; continue; }
      const x = this.wheelCenter(i, this._pt)[0];
      if (!this.skidOpen[i]) { const seg = [x, x]; this.skids[i].push(seg); this.skidOpen[i] = seg; }
      else this.skidOpen[i][1] = x;
    }
  }

  stateHash() {
    let h = 2166136261;
    const mix = (v) => { h ^= Math.round(v * 1e6) | 0; h = Math.imul(h, 16777619); };
    for (const b of this.world.bodies) { mix(b.x); mix(b.y); mix(b.a); mix(b.vx); mix(b.vy); }
    return (h >>> 0).toString(16).padStart(8, '0');
  }

  verdict() {
    if (this.impactT === null) return '';
    const f = this.displaced / this.pieces;
    const past = this.maxFront - SIM.wallX;
    let head;
    if (this.maxFront > this.wallEnd + 0.3) head = 'Car broke through the whole wall';
    else if (f > 0.5) head = 'Wall collapsed';
    else if (f > 0.04) head = 'Partial collapse';
    else head = 'Wall held';
    const parts = [
      `<b>${head}.</b> ${this.displaced} of ${this.pieces} pieces displaced (${Math.round(f * 100)}%)`,
      `car front reached ${past.toFixed(2)} m past the wall face`,
      `peak decel. ${this.peakDecel.toFixed(1)} g`,
    ];
    if (this.minVxAfter < -0.2) parts.push(`recoil ${(-this.minVxAfter).toFixed(1)} m/s`);
    return parts.join(' &middot; ');
  }

  summary() {
    const car = this.car;
    return {
      state: this.state,
      t: +this.t.toFixed(4),
      impactT: this.impactT === null ? null : +this.impactT.toFixed(4),
      impactSpeed: this.impactSpeed === null ? null : +this.impactSpeed.toFixed(3),
      carX: +car.x.toFixed(4),
      carVx: +car.vx.toFixed(4),
      carAngleDeg: +((car.a * 180) / Math.PI).toFixed(2),
      maxFrontPastWall: this.maxFront === -Infinity ? null : +(this.maxFront - SIM.wallX).toFixed(3),
      peakDecelG: +this.peakDecel.toFixed(2),
      crush: +this.crush.toFixed(3),
      pieces: this.pieces,
      displaced: this.displaced,
      moving: this.moving,
      minBrickY: +Math.min(...this.world.bricks.map((b) => b.minY)).toFixed(4),
      hash: this.stateHash(),
    };
  }
}

