const fs=require('fs');const f='prof/'+fs.readdirSync('prof').find(x=>x.endsWith('.cpuprofile'));const p=JSON.parse(fs.readFileSync(f));
const dt=p.timeDeltas;const idIdx=new Map(p.nodes.map(n=>[n.id,n]));
const counts=new Map();p.samples.forEach((s,i)=>counts.set(s,(counts.get(s)||0)+(dt[i]||0)));
const self=new Map();for(const [id,t] of counts){const n=idIdx.get(id);const k=n.callFrame.functionName+' L'+n.callFrame.lineNumber;self.set(k,(self.get(k)||0)+t);}
console.log([...self].sort((a,b)=>b[1]-a[1]).slice(0,15).map(([k,t])=>(t/1000).toFixed(0)+'ms '+k).join('\n'));
console.log(f);
"

