// Clip the incident segment against the two side planes of the reference edge.
// A clipped point keeps the id of the incident vertex it slid from, so warm
// starting survives the tiny rotations of perfectly aligned stacks.
const off1 = tx * v1x + ty * v1y;
let da = off1 - (tx * ax + ty * ay), db = off1 - (tx * bx + ty * by);
if (da > 0 && db > 0) return;
if (da > 0) { const u = da / (da - db); ax += u * (bx - ax); ay += u * (by - ay); }
else if (db > 0) { const u = db / (db - da); bx += u * (ax - bx); by += u * (ay - by); }

