// Bricks, per depth layer (layers are separate wythes and do not touch each other).
// Sweep-and-prune driven by awake bricks only: each awake brick scans forward
// for every neighbour and backward for sleeping ones, so a resting wall is free.
const window = BRICK_SPAN + 2 * SIM.maxExt;
for (let l = 0; l < this.layers.length; l++) {
  const L = this.layers[l];
  sortByKey(L);
  const n = L.length;
  for (let i = 0; i < n; i++) {
    const a = L[i];
    if (a.sleeping) continue;
    const aMax = a.maxX + a.ext;
    for (let j = i + 1; j < n; j++) {
      const b = L[j];
      if (b.key > aMax) break;
      this.brickPair(a, b, base, stamp);
    }
    const lo = a.key - window;
    for (let j = i - 1; j >= 0; j--) {
      const b = L[j];
      if (b.key < lo) break;
      if (b.sleeping && b.maxX >= a.key) this.brickPair(a, b, base, stamp);
    }
  }
}

