/* =====================================================================
   6. VISUAL EFFECTS (dust, chips, tyre smoke)
   Uses its own PRNG and never touches physics state.
   ===================================================================== */

class Effects {
  constructor() { this.reset(); }

  reset() {
    this.rng = mulberry32(0xc0ffee);
    this.dust = [];
    this.chips = [];
  }

  r(a, b) { return a + (b - a) * this.rng(); }

  puff(x, y, n, strength, color) {
    for (let i = 0; i < n && this.dust.length < 380; i++) {
      const life = this.r(0.9, 1.9);
      this.dust.push({
        x: x + this.r(-0.12, 0.12), y: Math.max(0.03, y + this.r(-0.05, 0.08)),
        vx: this.r(-1, 1) * (0.4 + strength * 0.05), vy: this.r(0.15, 0.7) + strength * 0.02,
        r: this.r(0.07, 0.16), grow: this.r(0.25, 0.55), life, max: life, color,
      });
    }
  }

  chip(x, y, n, strength, nx, ny) {
    for (let i = 0; i < n && this.chips.length < 320; i++) {
      const sp = this.r(0.25, 0.7) * Math.min(strength, 25);
      const ang = Math.atan2(ny, nx) + this.r(-1.3, 1.3);
      const life = this.r(1.2, 2.6);
      this.chips.push({
        x, y, vx: Math.cos(ang) * sp, vy: Math.abs(Math.sin(ang)) * sp * 0.8 + this.r(0.5, 2),
        a: this.r(0, 6.28), w: this.r(-18, 18), s: this.r(0.018, 0.045), life, max: life,
        color: this.rng() < 0.7 ? '#a24a33' : '#c9b8a3',
      });
    }
  }

  ingest(events, renderer) {
    for (const ev of events) {
      const s = ev.s;
      if (ev.k === 2) {
        if (s > 3) {
          this.chip(ev.x, ev.y, Math.min(10, (s * 0.4) | 0), s, -ev.nx, -ev.ny);
          this.puff(ev.x, ev.y, Math.min(5, (s * 0.2) | 0), s, '205,190,170');
          renderer.addShake(Math.min(9, s * 0.35));
        }
      } else if (ev.k === 1) {
        if (s > 2.5) this.puff(ev.x, 0.05, s > 6 ? 3 : 1, s, '196,178,150');
        if (s > 8) this.chip(ev.x, 0.05, 2, s * 0.4, 0, 1);
      } else if (ev.k === 0) {
        if (s > 6) this.chip(ev.x, ev.y, s > 12 ? 2 : 1, s * 0.5, ev.nx, ev.ny);
      } else if (ev.k === 3 && s > 3) {
        this.puff(ev.x, 0.05, 3, s, '170,160,150');
        renderer.addShake(Math.min(4, s * 0.3));
      }
    }
  }

  tyreSmoke(x, speed) {
    if (this.rng() > Math.min(1, speed / 10)) return;
    this.puff(x, 0.08, 1, 1, '215,215,215');
  }

  update(dt) {
    for (let i = this.dust.length - 1; i >= 0; i--) {
      const p = this.dust[i];
      p.life -= dt;
      if (p.life <= 0) { this.dust[i] = this.dust[this.dust.length - 1]; this.dust.pop(); continue; }
      p.x += p.vx * dt; p.y += p.vy * dt;
      p.vx *= 1 - 1.6 * dt; p.vy = p.vy * (1 - 1.2 * dt) + 0.05 * dt;
      p.r += p.grow * dt;
    }
    for (let i = this.chips.length - 1; i >= 0; i--) {
      const c = this.chips[i];
      c.life -= dt;
      if (c.life <= 0) { this.chips[i] = this.chips[this.chips.length - 1]; this.chips.pop(); continue; }
      c.vy -= 9.81 * dt;
      c.x += c.vx * dt; c.y += c.vy * dt; c.a += c.w * dt;
      if (c.y < c.s) { c.y = c.s; c.vy = -c.vy * 0.3; c.vx *= 0.6; c.w *= 0.5; }
    }
  }

  draw(ctx, R) {
    const S = R.S;
    for (const c of this.chips) {
      ctx.globalAlpha = Math.min(1, c.life / 0.5);
      ctx.fillStyle = c.color;
      const x = R.sx(c.x), y = R.sy(c.y), s = c.s * S;
      ctx.save(); ctx.translate(x, y); ctx.rotate(-c.a); ctx.fillRect(-s, -s * 0.6, s * 2, s * 1.2); ctx.restore();
    }
    for (const p of this.dust) {
      const k = p.life / p.max;
      ctx.globalAlpha = 0.32 * k * Math.min(1, (p.max - p.life) * 6);
      ctx.fillStyle = `rgb(${p.color})`;
      ctx.beginPath(); ctx.arc(R.sx(p.x), R.sy(p.y), p.r * S, 0, 6.2832); ctx.fill();
    }
    ctx.globalAlpha = 1;
  }
}

/* =====================================================================
   7. RENDERER
   World units are metres with y up; screen = (x - camX) * 80 px, ground
   line fixed on screen. Physics never reads anything from here.
   ===================================================================== */

const BRICK_BASE = [[166, 72, 50], [178, 84, 60], [154, 63, 46], [188, 96, 68], [170, 79, 56], [149, 66, 50]];
const HAZE = [132, 146, 160];

class Renderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { alpha: false });
    this.dpr = 1; this.W = 0; this.H = 0;
    this.S = FIXED.pxPerM;
    this.groundY = 0;
    this.camX = -10; this.camHome = -10;
    this.follow = true;
    this.shakeAmp = 0; this.shakeX = 0; this.shakeY = 0; this.shakeT = 0;
    this.brickFills = [];
    for (let k = 0; k < 5; k++) {
      const t = Math.min(0.55, 0.14 * k), d = 1 - 0.07 * k;
      this.brickFills.push(BRICK_BASE.map((c) => {
        const m = c.map((v, i) => Math.round((v * (1 - t) + HAZE[i] * t) * d));
        return `rgb(${m[0]},${m[1]},${m[2]})`;
      }));
    }
    this.visual = null;
  }

  resize(bottomReserve) {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const W = window.innerWidth, H = window.innerHeight;
    this.dpr = dpr; this.W = W; this.H = H;
    this.canvas.width = Math.round(W * dpr);
    this.canvas.height = Math.round(H * dpr);
    this.groundY = Math.round(Math.max(Math.min(H - bottomReserve, H - 90), Math.min(H * 0.62, 380)));
    this.skyGrad = null;
  }

  viewW() { return this.W / this.S; }
  sx(x) { return (x - this.camX) * this.S + this.shakeX; }
  sy(y) { return this.groundY - y * this.S + this.shakeY; }

  frame(exp) {
    const left = SIM.wallX - SIM.runup - FIXED.carW - 0.7;
    const right = exp.wallEnd + 0.9;
    const vw = this.viewW();
    this.camHome = right - left <= vw ? left - (vw - (right - left)) / 2 : left;
    this.camX = this.camHome;
    this.shakeAmp = 0;
    this.visual = { pitch: 0, pitchV: 0, bob: 0, bobV: 0, lurch: 0, lurchV: 0, wheelA: 0, lastVx: 0, lastVy: 0 };
  }

  addShake(a) { this.shakeAmp = Math.min(14, this.shakeAmp + a); }

  update(dt, simDt, exp) {
    if (this.follow && exp.state !== 'ready') {
      const target = Math.max(this.camHome, exp.carFrontX() - this.viewW() * 0.62);
      this.camX += (target - this.camX) * (1 - Math.exp(-dt * 3.5));
    }
    this.shakeT += dt;
    this.shakeAmp *= Math.exp(-dt * 7);
    this.shakeX = Math.sin(this.shakeT * 83) * this.shakeAmp;
    this.shakeY = Math.cos(this.shakeT * 67) * this.shakeAmp * 0.6;

    // Cosmetic suspension, dummy lurch and wheel spin driven by the car's actual acceleration.
    const v = this.visual, car = exp.car;
    if (simDt > 0) {
      const ax = clamp((car.vx - v.lastVx) / simDt, -400, 400);
      const ay = clamp((car.vy - v.lastVy) / simDt, -400, 400);
      v.lastVx = car.vx; v.lastVy = car.vy;
      const sd = simDt;
      v.pitchV += ((clamp(ax * 0.0016, -0.085, 0.06) - v.pitch) * 140 - v.pitchV * 11) * sd;
      v.pitch += v.pitchV * sd;
      v.bobV += ((clamp(-ay * 0.0006, -0.05, 0.05) - v.bob) * 160 - v.bobV * 12) * sd;
      v.bob += v.bobV * sd;
      v.lurchV += ((clamp(-ax * 0.0009, -0.05, 0.26) - v.lurch) * 90 - v.lurchV * 9) * sd;
      v.lurch += v.lurchV * sd;
      if (!exp.world.wheelsLocked) v.wheelA -= ((car.vx * car.c + car.vy * car.s) * sd) / CAR_DESIGN.wheelR;
    }
  }

  draw(exp, fx, alpha) {
    const ctx = this.ctx;
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.drawSky(ctx);
    this.drawFar(ctx);
    this.drawBoard(ctx, exp);
    this.drawGround(ctx, exp);
    this.drawSkids(ctx, exp);
    const layers = exp.world.layers;
    for (let k = layers.length - 1; k >= 1; k--) this.drawLayer(ctx, layers[k], k, alpha);
    this.drawCar(ctx, exp, alpha);
    if (layers.length) this.drawLayer(ctx, layers[0], 0, alpha);
    fx.draw(ctx, this);
    this.drawRuler(ctx);
    if (exp.state === 'ready') this.drawTags(ctx, exp);
  }

  drawSky(ctx) {
    if (!this.skyGrad) {
      const g = ctx.createLinearGradient(0, 0, 0, this.groundY);
      g.addColorStop(0, '#6fa6d6'); g.addColorStop(0.5, '#a9cbe6'); g.addColorStop(1, '#efe3cf');
      this.skyGrad = g;
    }
    ctx.fillStyle = this.skyGrad;
    ctx.fillRect(0, 0, this.W, this.groundY);
    const sun = ctx.createRadialGradient(this.W * 0.82, this.groundY * 0.28, 0, this.W * 0.82, this.groundY * 0.28, 260);
    sun.addColorStop(0, 'rgba(255,248,225,0.85)'); sun.addColorStop(0.2, 'rgba(255,240,205,0.35)'); sun.addColorStop(1, 'rgba(255,240,205,0)');
    ctx.fillStyle = sun;
    ctx.fillRect(0, 0, this.W, this.groundY);
  }

  drawFar(ctx) {
    const W = this.W, gy = this.groundY, S = this.S;
    const ridge = (par, base, amp, f1, f2, color) => {
      const off = this.camX * S * par;
      ctx.beginPath(); ctx.moveTo(0, gy);
      for (let x = 0; x <= W + 20; x += 20) {
        const u = (x + off) / S;
        ctx.lineTo(x, gy - base - amp * (Math.sin(u * f1) * 0.6 + Math.sin(u * f2 + 1.7) * 0.4));
      }
      ctx.lineTo(W, gy); ctx.closePath(); ctx.fillStyle = color; ctx.fill();
    };
    ridge(0.08, 70, 34, 0.11, 0.29, '#b3c8d4');
    // Test facility hangars
    const par = 0.2, off = this.camX * S * par;
    for (let i = Math.floor(off / 700) - 1; i <= Math.floor((off + W) / 700) + 1; i++) {
      const hs = hash32(i + 1000);
      const x = i * 700 - off + (hs % 200);
      const w = 180 + (hs >>> 8) % 140, h = 46 + (hs >>> 16) % 30;
      ctx.fillStyle = '#a4b3bd';
      ctx.fillRect(x, gy - h - 22, w, h + 22);
      ctx.beginPath(); ctx.moveTo(x - 6, gy - h - 22); ctx.lineTo(x + w / 2, gy - h - 44); ctx.lineTo(x + w + 6, gy - h - 22); ctx.fill();
      ctx.fillStyle = 'rgba(70,90,105,0.25)';
      for (let k = 0; k < 5; k++) ctx.fillRect(x + 14 + k * (w - 28) / 5, gy - h - 8, (w - 28) / 5 - 8, 10);
    }
    ridge(0.3, 16, 9, 0.8, 2.1, '#8faa92');
  }

  drawBoard(ctx, exp) {
    // Measurement backdrop behind the test zone: 0.5 m grid, 4 m tall.
    const S = this.S;
    const x0 = Math.max(this.sx(-14), -20), x1 = Math.min(this.sx(Math.max(exp.wallEnd + 16, 28)), this.W + 20);
    if (x1 <= x0) return;
    const top = this.sy(4), bottom = this.sy(0);
    ctx.fillStyle = 'rgba(250,248,242,0.42)';
    ctx.fillRect(x0, top, x1 - x0, bottom - top);
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let y = 0.5; y <= 4.001; y += 0.5) { const py = Math.round(this.sy(y)) + 0.5; ctx.moveTo(x0, py); ctx.lineTo(x1, py); }
    const first = Math.ceil((this.camX - 1) * 2) / 2;
    for (let x = first; x <= this.camX + this.viewW() + 1; x += 0.5) {
      const px = Math.round(this.sx(x)) + 0.5;
      if (px < x0 || px > x1) continue;
      ctx.moveTo(px, top); ctx.lineTo(px, bottom);
    }
    ctx.strokeStyle = 'rgba(60,85,110,0.13)';
    ctx.stroke();
    ctx.fillStyle = 'rgba(40,50,60,0.55)';
    ctx.fillRect(x0, top - 3, x1 - x0, 3);
  }

  drawGround(ctx, exp) {
    const W = this.W, H = this.H, gy = this.groundY + this.shakeY, S = this.S;
    const band = 20;
    const road = ctx.createLinearGradient(0, gy - band, 0, gy);
    road.addColorStop(0, '#9a9b9c'); road.addColorStop(1, '#78797b');
    ctx.fillStyle = road; ctx.fillRect(0, gy - band, W, band);
    ctx.fillStyle = '#3a3c40'; ctx.fillRect(0, gy, W, 22);
    ctx.fillStyle = '#6e5d4b'; ctx.fillRect(0, gy + 22, W, 8);
    const soil = ctx.createLinearGradient(0, gy + 30, 0, H);
    soil.addColorStop(0, '#5a4737'); soil.addColorStop(1, '#271f19');
    ctx.fillStyle = soil; ctx.fillRect(0, gy + 30, W, H - gy - 30);
    ctx.fillStyle = 'rgba(255,255,255,0.08)'; ctx.fillRect(0, gy, W, 1);

    // Start line (checkered) at the car's bumper start position.
    const sx0 = this.sx(SIM.wallX - SIM.runup);
    if (sx0 > -20 && sx0 < W + 20) {
      const cs = band / 4;
      for (let i = 0; i < 4; i++) for (let j = 0; j < 2; j++) {
        ctx.fillStyle = (i + j) % 2 ? '#111' : '#eee';
        ctx.fillRect(sx0 - cs * 2 + j * cs, gy - band + i * cs, cs, cs);
      }
    }

    // Distance ticks relative to the wall face.
    ctx.font = '600 10px ui-monospace, SFMono-Regular, Menlo, monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const m0 = Math.floor(this.camX) - 1, m1 = Math.ceil(this.camX + this.viewW()) + 1;
    for (let m = m0; m <= m1; m++) {
      const px = Math.round(this.sx(SIM.wallX + m)) + 0.5;
      const major = m % 5 === 0;
      ctx.strokeStyle = m === 0 ? '#ffb81c' : major ? 'rgba(255,255,255,0.7)' : 'rgba(255,255,255,0.35)';
      ctx.lineWidth = m === 0 ? 2 : 1;
      ctx.beginPath(); ctx.moveTo(px, gy); ctx.lineTo(px, gy + (major ? 9 : 5)); ctx.stroke();
      if (major || m === -1 || m === 1 || (m > 0 && m < 3)) {
        ctx.fillStyle = m === 0 ? '#ffb81c' : 'rgba(255,255,255,0.62)';
        ctx.fillText(m === 0 ? '0 m' : `${m}`, px, gy + 15);
      }
    }
  }

  drawSkids(ctx, exp) {
    const gy = this.groundY + this.shakeY;
    ctx.fillStyle = 'rgba(25,25,28,0.55)';
    for (let i = 0; i < 2; i++) {
      for (const [a, b] of exp.skids[i]) {
        const x0 = this.sx(Math.min(a, b)), x1 = this.sx(Math.max(a, b));
        if (x1 < -5 || x0 > this.W + 5) continue;
        ctx.fillRect(x0, gy - 7 - i * 2, Math.max(1, x1 - x0), 4);
      }
    }
  }

  drawLayer(ctx, bricks, k, alpha) {
    const S = this.S, fills = this.brickFills[Math.min(k, 4)];
    const ox = k * 3 + this.shakeX - this.camX * S, oy = -k * 4 + this.groundY + this.shakeY;
    const inset = 0.7 / S;
    const paths = [new Path2D(), new Path2D(), new Path2D(), new Path2D(), new Path2D(), new Path2D()];
    const lit = new Path2D(), dark = new Path2D();
    for (let i = 0; i < bricks.length; i++) {
      const b = bricks[i];
      const x = b.px + (b.x - b.px) * alpha, y = b.py + (b.y - b.py) * alpha, a = b.pa + (b.a - b.pa) * alpha;
      const c = Math.cos(a), s = Math.sin(a);
      const hw = (b.hw - inset) * S, hh = (b.hh - inset) * S;
      const cx = x * S + ox, cy = oy - y * S;
      const ux = c * hw, uy = -s * hw, vx = -s * hh, vy = -c * hh;
      const p = paths[b.shade];
      p.moveTo(cx - ux - vx, cy - uy - vy);
      p.lineTo(cx + ux - vx, cy + uy - vy);
      p.lineTo(cx + ux + vx, cy + uy + vy);
      p.lineTo(cx - ux + vx, cy - uy + vy);
      p.closePath();
      lit.moveTo(cx - ux + vx, cy - uy + vy); lit.lineTo(cx + ux + vx, cy + uy + vy);
      dark.moveTo(cx - ux - vx, cy - uy - vy); dark.lineTo(cx + ux - vx, cy + uy - vy);
    }
    for (let q = 0; q < 6; q++) { ctx.fillStyle = fills[q]; ctx.fill(paths[q]); }
    ctx.lineWidth = 1.3;
    ctx.strokeStyle = `rgba(255,214,180,${0.32 - k * 0.05})`; ctx.stroke(lit);
    ctx.strokeStyle = 'rgba(40,14,8,0.38)'; ctx.stroke(dark);
    ctx.lineWidth = 0.8;
    ctx.strokeStyle = 'rgba(52,26,18,0.55)';
    for (let q = 0; q < 6; q++) ctx.stroke(paths[q]);
  }

  drawCar(ctx, exp, alpha) {
    const car = exp.car, S = this.S, dpr = this.dpr, v = this.visual, crush = exp.crush;
    const x = car.px + (car.x - car.px) * alpha, y = car.py + (car.y - car.py) * alpha, a = car.pa + (car.a - car.pa) * alpha;
    const speed = Math.hypot(car.vx, car.vy);

    // Contact shadow.
    const bottom = Math.max(0, y - car.com.y);
    ctx.fillStyle = `rgba(0,0,0,${0.32 * clamp(1 - bottom / 1.5, 0, 1)})`;
    ctx.beginPath();
    ctx.ellipse(this.sx(x - car.com.x * Math.cos(a)), this.groundY + this.shakeY - 2, 2.25 * S, 0.1 * S, 0, 0, 6.2832);
    ctx.fill();

    // Speed streaks.
    if (speed > 8 && exp.state === 'launch') {
      ctx.strokeStyle = `rgba(255,255,255,${Math.min(0.5, (speed - 8) / 40)})`;
      ctx.lineWidth = 2;
      for (let i = 0; i < 4; i++) {
        const yy = this.sy(y - car.com.y + 0.35 + i * 0.28);
        const x0 = this.sx(x - car.com.x - 2.2), len = speed * (3 + i);
        ctx.beginPath(); ctx.moveTo(x0 - 6, yy); ctx.lineTo(x0 - 6 - len, yy); ctx.stroke();
      }
    }

    ctx.save();
    ctx.setTransform(dpr * S, 0, 0, -dpr * S, dpr * this.sx(x), dpr * this.sy(y));
    ctx.rotate(a);
    ctx.translate(-car.com.x, -car.com.y);
    const px = 1 / S;

    ctx.save();
    ctx.translate(0, 0.45 + v.bob); ctx.rotate(v.pitch); ctx.translate(0, -0.45);
    this.drawCarBody(ctx, crush, px, v);
    ctx.restore();

    for (let i = 0; i < 2; i++) this.drawWheel(ctx, CAR_DESIGN.wheelX[i], WHEEL_AP, v.wheelA, px);
    ctx.restore();
  }

  drawCarBody(ctx, c, px, v) {
    const X = (x) => crushX(x, c);
    const hb = c * 0.32;
    const outline = () => {
      ctx.beginPath();
      ctx.moveTo(-2.08, 0.30);
      ctx.lineTo(-2.13, 0.52);
      ctx.quadraticCurveTo(-2.15, 0.79, -2.02, 0.87);
      ctx.lineTo(-1.80, 0.95);
      ctx.quadraticCurveTo(-1.45, 1.22, -1.05, 1.42);
      ctx.quadraticCurveTo(-0.45, 1.47, 0.12, 1.44);
      ctx.quadraticCurveTo(0.55, 1.22, 1.02, 0.94);
      ctx.quadraticCurveTo(X(1.45), 0.93 + hb, X(1.88), 0.87 + hb * 0.3);
      ctx.quadraticCurveTo(X(2.08), 0.83, X(2.11), 0.70);
      ctx.lineTo(X(2.13), 0.42);
      ctx.quadraticCurveTo(X(2.12), 0.28, Math.max(1.84, X(1.95)), 0.26);
      ctx.lineTo(1.82, 0.25);
      ctx.arc(1.40, WHEEL_AP, 0.41, -0.18, Math.PI + 0.18, false);
      ctx.lineTo(-0.94, 0.245);
      ctx.arc(-1.35, WHEEL_AP, 0.41, -0.18, Math.PI + 0.18, false);
      ctx.lineTo(-1.95, 0.26);
      ctx.quadraticCurveTo(-2.07, 0.27, -2.08, 0.30);
      ctx.closePath();
    };

    const paint = ctx.createLinearGradient(0, 0.25, 0, 1.45);
    paint.addColorStop(0, '#163f86'); paint.addColorStop(0.35, '#2462c4'); paint.addColorStop(0.6, '#3f86e6'); paint.addColorStop(0.62, '#2a66c8'); paint.addColorStop(1, '#2d6bd0');
    outline();
    ctx.fillStyle = paint; ctx.fill();
    ctx.lineWidth = 1.4 * px; ctx.strokeStyle = 'rgba(8,18,40,0.85)'; ctx.stroke();

    ctx.save();
    outline(); ctx.clip();
    // Test-vehicle stripe and shoulder highlight.
    ctx.fillStyle = '#ffb81c';
    ctx.fillRect(-2.2, 0.50, 4.5, 0.07);
    ctx.strokeStyle = 'rgba(255,255,255,0.35)'; ctx.lineWidth = 2 * px;
    ctx.beginPath(); ctx.moveTo(-1.95, 0.91); ctx.lineTo(X(1.8), 0.87 + hb * 0.3); ctx.stroke();
    // Bumpers.
    ctx.fillStyle = '#25282d';
    ctx.fillRect(X(1.9), 0.2, 0.4, 0.26);
    ctx.fillRect(-2.25, 0.2, 0.33, 0.26);
    // Crumple creases.
    if (c > 0.02) {
      ctx.strokeStyle = 'rgba(5,10,25,0.55)'; ctx.lineWidth = 1.5 * px;
      const n = Math.min(6, Math.ceil(c * 16));
      for (let i = 0; i < n; i++) {
        const xx = X(1.55 + i * 0.09);
        ctx.beginPath(); ctx.moveTo(xx, 0.3 + (i % 2) * 0.1); ctx.lineTo(xx + 0.06, 0.62); ctx.lineTo(xx - 0.02, 0.9 + hb * 0.5); ctx.stroke();
      }
    }
    ctx.restore();

    // Glass, with the crash dummy inside.
    const glass = () => {
      ctx.beginPath();
      ctx.moveTo(-1.70, 0.98);
      ctx.quadraticCurveTo(-1.40, 1.20, -1.02, 1.37);
      ctx.quadraticCurveTo(-0.45, 1.41, 0.08, 1.38);
      ctx.quadraticCurveTo(0.50, 1.18, 0.92, 0.97);
      ctx.closePath();
    };
    glass();
    const gg = ctx.createLinearGradient(0, 0.97, 0, 1.4);
    gg.addColorStop(0, '#1a2632'); gg.addColorStop(1, '#4a6376');
    ctx.fillStyle = gg; ctx.fill();
    ctx.save();
    glass(); ctx.clip();
    const lx = -0.2 + v.lurch;
    ctx.fillStyle = '#e8b43a';
    ctx.beginPath(); ctx.arc(lx, 1.19, 0.09, 0, 6.2832); ctx.fill();
    ctx.fillRect(lx - 0.16, 0.95, 0.26, 0.15);
    ctx.fillStyle = '#111';
    ctx.beginPath(); ctx.arc(lx, 1.19, 0.035, 0, 6.2832); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.14)';
    ctx.beginPath(); ctx.moveTo(-0.9, 0.97); ctx.lineTo(-0.6, 0.97); ctx.lineTo(-0.2, 1.42); ctx.lineTo(-0.5, 1.42); ctx.fill();
    if (c > 0.1) {
      ctx.strokeStyle = 'rgba(235,245,255,0.8)'; ctx.lineWidth = 1 * px;
      const cx0 = 0.55, cy0 = 1.14;
      for (let i = 0; i < 7; i++) {
        const t = i * 0.9;
        ctx.beginPath(); ctx.moveTo(cx0, cy0); ctx.lineTo(cx0 + Math.cos(t) * 0.3, cy0 + Math.sin(t) * 0.3); ctx.stroke();
      }
    }
    ctx.restore();
    ctx.fillStyle = '#1d4fa3';
    ctx.fillRect(-0.47, 0.95, 0.08, 0.45);
    ctx.lineWidth = 1.2 * px; ctx.strokeStyle = 'rgba(8,18,40,0.8)'; glass(); ctx.stroke();

    // Doors, handles, mirror.
    ctx.strokeStyle = 'rgba(5,15,35,0.55)'; ctx.lineWidth = 1.2 * px;
    ctx.beginPath();
    ctx.moveTo(-0.43, 0.30); ctx.lineTo(-0.43, 0.95);
    ctx.moveTo(0.88, 0.34); ctx.quadraticCurveTo(0.95, 0.65, 0.9, 0.95);
    ctx.moveTo(-1.52, 0.36); ctx.quadraticCurveTo(-1.58, 0.7, -1.62, 0.96);
    ctx.stroke();
    ctx.fillStyle = 'rgba(10,20,40,0.7)';
    ctx.fillRect(0.28, 0.78, 0.16, 0.035);
    ctx.fillRect(-1.02, 0.78, 0.16, 0.035);
    ctx.fillStyle = '#1b4592';
    ctx.beginPath(); ctx.moveTo(0.86, 0.97); ctx.lineTo(1.02, 0.99); ctx.lineTo(1.0, 1.07); ctx.lineTo(0.88, 1.06); ctx.fill();

    // Crash-test calibration markers.
    this.marker(ctx, 0.25, 0.72, 0.1);
    this.marker(ctx, -1.05, 0.72, 0.1);
    this.marker(ctx, -1.38, 1.13, 0.065);

    // Lights.
    if (c < 0.06) {
      ctx.fillStyle = '#fff4c8';
      ctx.beginPath(); ctx.ellipse(X(2.04), 0.72, 0.07, 0.05, 0, 0, 6.2832); ctx.fill();
    } else {
      ctx.fillStyle = '#4b4f55';
      ctx.beginPath(); ctx.ellipse(X(2.04), 0.72, 0.06, 0.045, 0, 0, 6.2832); ctx.fill();
    }
    ctx.fillStyle = '#d42a3d';
    ctx.fillRect(-2.13, 0.64, 0.08, 0.16);
  }

  marker(ctx, x, y, r) {
    for (let q = 0; q < 4; q++) {
      ctx.beginPath(); ctx.moveTo(x, y); ctx.arc(x, y, r, (q * Math.PI) / 2, ((q + 1) * Math.PI) / 2); ctx.closePath();
      ctx.fillStyle = q % 2 ? '#111' : '#ffd21f'; ctx.fill();
    }
  }

  drawWheel(ctx, x, y, ang, px) {
    ctx.fillStyle = '#16171a';
    ctx.beginPath(); ctx.arc(x, y, CAR_DESIGN.wheelR, 0, 6.2832); ctx.fill();
    ctx.strokeStyle = '#2d2f34'; ctx.lineWidth = 0.03;
    ctx.beginPath(); ctx.arc(x, y, 0.29, 0, 6.2832); ctx.stroke();
    const rim = ctx.createRadialGradient(x - 0.05, y + 0.05, 0.02, x, y, 0.21);
    rim.addColorStop(0, '#f1f3f6'); rim.addColorStop(1, '#8b939c');
    ctx.fillStyle = rim;
    ctx.beginPath(); ctx.arc(x, y, 0.21, 0, 6.2832); ctx.fill();
    ctx.fillStyle = '#3a3e45';
    for (let k = 0; k < 5; k++) {
      const t = ang + (k * 2 * Math.PI) / 5;
      ctx.beginPath();
      ctx.arc(x, y, 0.17, t - 0.28, t + 0.28);
      ctx.arc(x, y, 0.07, t + 0.4, t - 0.4, true);
      ctx.closePath(); ctx.fill();
    }
    ctx.fillStyle = '#5b6068';
    ctx.beginPath(); ctx.arc(x, y, 0.045, 0, 6.2832); ctx.fill();
    ctx.lineWidth = 1 * px; ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.beginPath(); ctx.arc(x, y, 0.21, 0, 6.2832); ctx.stroke();
  }

  drawRuler(ctx) {
    // Height ruler on the left edge (screen-fixed, world-scaled).
    const x = 10;
    ctx.strokeStyle = 'rgba(20,30,40,0.55)'; ctx.fillStyle = 'rgba(20,30,40,0.7)';
    ctx.lineWidth = 1;
    ctx.font = '600 10px ui-monospace, SFMono-Regular, Menlo, monospace';
    ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
    ctx.beginPath(); ctx.moveTo(x + 0.5, this.sy(0)); ctx.lineTo(x + 0.5, this.sy(4)); ctx.stroke();
    for (let h = 0; h <= 8; h++) {
      const py = Math.round(this.sy(h * 0.5)) + 0.5;
      ctx.beginPath(); ctx.moveTo(x, py); ctx.lineTo(x + (h % 2 ? 5 : 9), py); ctx.stroke();
      if (h % 2 === 0 && h > 0) ctx.fillText(`${h / 2} m`, x + 12, py);
    }
    ctx.fillText('80 px/m', x + 12, this.sy(4) - 12);
  }

  drawTags(ctx, exp) {
    const s = exp.settings;
    const carTop = this.sy(1.45) - 16;
    this.tag(ctx, this.sx(SIM.wallX - SIM.runup - FIXED.carW / 2), carTop, `Car \u00b7 ${s.carMass.toLocaleString('en-US')} kg \u00b7 ${s.carSpeed.toFixed(1)} m/s`);
    const wallTop = this.sy(s.rows * FIXED.brickH) - 18 - (s.layers - 1) * 4;
    this.tag(ctx, this.sx((SIM.wallX + exp.wallEnd) / 2), wallTop, `Wall \u00b7 ${s.cols}\u00d7${s.rows}\u00d7${s.layers} \u00b7 ${exp.pieces} pieces \u00b7 ${exp.wallMass.toFixed(0)} kg`);
  }

  tag(ctx, x, y, text) {
    ctx.font = '600 12px -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
    const w = ctx.measureText(text).width + 20, h = 24;
    x = clamp(x, w / 2 + 8, this.W - w / 2 - 8);
    ctx.fillStyle = 'rgba(14,17,22,0.78)';
    ctx.beginPath(); ctx.roundRect(x - w / 2, y - h / 2, w, h, 12); ctx.fill();
    ctx.beginPath(); ctx.moveTo(x - 5, y + h / 2); ctx.lineTo(x + 5, y + h / 2); ctx.lineTo(x, y + h / 2 + 6); ctx.fill();
    ctx.fillStyle = '#f2f4f7'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(text, x, y + 0.5);
  }
}

/*__UI__*/

/* =====================================================================
   6. VISUAL EFFECTS (dust, chips, tyre smoke)
   Uses its own PRNG and never touches physics state.
   ===================================================================== */

class Effects {
  constructor() { this.reset(); }

  reset() {
    this.rng = mulberry32(0xc0ffee);
    this.dust = [];
    this.chips = [];
  }

  r(a, b) { return a + (b - a) * this.rng(); }

  puff(x, y, n, strength, color) {
    for (let i = 0; i < n && this.dust.length < 380; i++) {
      const life = this.r(0.9, 1.9);
      this.dust.push({
        x: x + this.r(-0.12, 0.12), y: Math.max(0.03, y + this.r(-0.05, 0.08)),
        vx: this.r(-1, 1) * (0.4 + strength * 0.05), vy: this.r(0.15, 0.7) + strength * 0.02,
        r: this.r(0.07, 0.16), grow: this.r(0.25, 0.55), life, max: life, color,
      });
    }
  }

  chip(x, y, n, strength, nx, ny) {
    for (let i = 0; i < n && this.chips.length < 320; i++) {
      const sp = this.r(0.25, 0.7) * Math.min(strength, 25);
      const ang = Math.atan2(ny, nx) + this.r(-1.3, 1.3);
      const life = this.r(1.2, 2.6);
      this.chips.push({
        x, y, vx: Math.cos(ang) * sp, vy: Math.abs(Math.sin(ang)) * sp * 0.8 + this.r(0.5, 2),
        a: this.r(0, 6.28), w: this.r(-18, 18), s: this.r(0.018, 0.045), life, max: life,
        color: this.rng() < 0.7 ? '#a24a33' : '#c9b8a3',
      });
    }
  }

  ingest(events, renderer) {
    for (const ev of events) {
      const s = ev.s;
      if (ev.k === 2) {
        if (s > 3) {
          this.chip(ev.x, ev.y, Math.min(10, (s * 0.4) | 0), s, -ev.nx, -ev.ny);
          this.puff(ev.x, ev.y, Math.min(5, (s * 0.2) | 0), s, '205,190,170');
          renderer.addShake(Math.min(9, s * 0.35));
        }
      } else if (ev.k === 1) {
        if (s > 2.5) this.puff(ev.x, 0.05, s > 6 ? 3 : 1, s, '196,178,150');
        if (s > 8) this.chip(ev.x, 0.05, 2, s * 0.4, 0, 1);
      } else if (ev.k === 0) {
        if (s > 6) this.chip(ev.x, ev.y, s > 12 ? 2 : 1, s * 0.5, ev.nx, ev.ny);
      } else if (ev.k === 3 && s > 3) {
        this.puff(ev.x, 0.05, 3, s, '170,160,150');
        renderer.addShake(Math.min(4, s * 0.3));
      }
    }
  }

  tyreSmoke(x, speed) {
    if (this.rng() > Math.min(1, speed / 10)) return;
    this.puff(x, 0.08, 1, 1, '215,215,215');
  }

  update(dt) {
    for (let i = this.dust.length - 1; i >= 0; i--) {
      const p = this.dust[i];
      p.life -= dt;
      if (p.life <= 0) { this.dust[i] = this.dust[this.dust.length - 1]; this.dust.pop(); continue; }
      p.x += p.vx * dt; p.y += p.vy * dt;
      p.vx *= 1 - 1.6 * dt; p.vy = p.vy * (1 - 1.2 * dt) + 0.05 * dt;
      p.r += p.grow * dt;
    }
    for (let i = this.chips.length - 1; i >= 0; i--) {
      const c = this.chips[i];
      c.life -= dt;
      if (c.life <= 0) { this.chips[i] = this.chips[this.chips.length - 1]; this.chips.pop(); continue; }
      c.vy -= 9.81 * dt;
      c.x += c.vx * dt; c.y += c.vy * dt; c.a += c.w * dt;
      if (c.y < c.s) { c.y = c.s; c.vy = -c.vy * 0.3; c.vx *= 0.6; c.w *= 0.5; }
    }
  }

  draw(ctx, R) {
    const S = R.S;
    for (const c of this.chips) {
      ctx.globalAlpha = Math.min(1, c.life / 0.5);
      ctx.fillStyle = c.color;
      const x = R.sx(c.x), y = R.sy(c.y), s = c.s * S;
      ctx.save(); ctx.translate(x, y); ctx.rotate(-c.a); ctx.fillRect(-s, -s * 0.6, s * 2, s * 1.2); ctx.restore();
    }
    for (const p of this.dust) {
      const k = p.life / p.max;
      ctx.globalAlpha = 0.32 * k * Math.min(1, (p.max - p.life) * 6);
      ctx.fillStyle = `rgb(${p.color})`;
      ctx.beginPath(); ctx.arc(R.sx(p.x), R.sy(p.y), p.r * S, 0, 6.2832); ctx.fill();
    }
    ctx.globalAlpha = 1;
  }
}

/* =====================================================================
   7. RENDERER
   World units are metres with y up; screen = (x - camX) * 80 px, ground
   line fixed on screen. Physics never reads anything from here.
   ===================================================================== */

const BRICK_BASE = [[166, 72, 50], [178, 84, 60], [154, 63, 46], [188, 96, 68], [170, 79, 56], [149, 66, 50]];
const HAZE = [132, 146, 160];

class Renderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { alpha: false });
    this.dpr = 1; this.W = 0; this.H = 0;
    this.S = FIXED.pxPerM;
    this.groundY = 0;
    this.camX = -10; this.camHome = -10;
    this.follow = true;
    this.shakeAmp = 0; this.shakeX = 0; this.shakeY = 0; this.shakeT = 0;
    this.brickFills = [];
    for (let k = 0; k < 5; k++) {
      const t = Math.min(0.55, 0.14 * k), d = 1 - 0.07 * k;
      this.brickFills.push(BRICK_BASE.map((c) => {
        const m = c.map((v, i) => Math.round((v * (1 - t) + HAZE[i] * t) * d));
        return `rgb(${m[0]},${m[1]},${m[2]})`;
      }));
    }
    this.visual = null;
  }

  resize(bottomReserve) {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const W = window.innerWidth, H = window.innerHeight;
    this.dpr = dpr; this.W = W; this.H = H;
    this.canvas.width = Math.round(W * dpr);
    this.canvas.height = Math.round(H * dpr);
    this.groundY = Math.round(Math.max(Math.min(H - bottomReserve, H - 90), Math.min(H * 0.62, 380)));
    this.skyGrad = null;
  }

  viewW() { return this.W / this.S; }
  sx(x) { return (x - this.camX) * this.S + this.shakeX; }
  sy(y) { return this.groundY - y * this.S + this.shakeY; }

  frame(exp) {
    const left = SIM.wallX - SIM.runup - FIXED.carW - 0.7;
    const right = exp.wallEnd + 0.9;
    const vw = this.viewW();
    this.camHome = right - left <= vw ? left - (vw - (right - left)) / 2 : left;
    this.camX = this.camHome;
    this.shakeAmp = 0;
    this.visual = { pitch: 0, pitchV: 0, bob: 0, bobV: 0, lurch: 0, lurchV: 0, wheelA: 0, lastVx: 0, lastVy: 0 };
  }

  addShake(a) { this.shakeAmp = Math.min(14, this.shakeAmp + a); }

  update(dt, simDt, exp) {
    if (this.follow && exp.state !== 'ready') {
      const target = Math.max(this.camHome, exp.carFrontX() - this.viewW() * 0.62);
      this.camX += (target - this.camX) * (1 - Math.exp(-dt * 3.5));
    }
    this.shakeT += dt;
    this.shakeAmp *= Math.exp(-dt * 7);
    this.shakeX = Math.sin(this.shakeT * 83) * this.shakeAmp;
    this.shakeY = Math.cos(this.shakeT * 67) * this.shakeAmp * 0.6;

    // Cosmetic suspension, dummy lurch and wheel spin driven by the car's actual acceleration.
    const v = this.visual, car = exp.car;
    if (simDt > 0) {
      const ax = clamp((car.vx - v.lastVx) / simDt, -400, 400);
      const ay = clamp((car.vy - v.lastVy) / simDt, -400, 400);
      v.lastVx = car.vx; v.lastVy = car.vy;
      const sd = simDt;
      v.pitchV += ((clamp(ax * 0.0016, -0.085, 0.06) - v.pitch) * 140 - v.pitchV * 11) * sd;
      v.pitch += v.pitchV * sd;
      v.bobV += ((clamp(-ay * 0.0006, -0.05, 0.05) - v.bob) * 160 - v.bobV * 12) * sd;
      v.bob += v.bobV * sd;
      v.lurchV += ((clamp(-ax * 0.0009, -0.05, 0.26) - v.lurch) * 90 - v.lurchV * 9) * sd;
      v.lurch += v.lurchV * sd;
      if (!exp.world.wheelsLocked) v.wheelA -= ((car.vx * car.c + car.vy * car.s) * sd) / CAR_DESIGN.wheelR;
    }
  }

  draw(exp, fx, alpha) {
    const ctx = this.ctx;
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.drawSky(ctx);
    this.drawFar(ctx);
    this.drawBoard(ctx, exp);
    this.drawGround(ctx, exp);
    this.drawSkids(ctx, exp);
    const layers = exp.world.layers;
    for (let k = layers.length - 1; k >= 1; k--) this.drawLayer(ctx, layers[k], k, alpha);
    this.drawCar(ctx, exp, alpha);
    if (layers.length) this.drawLayer(ctx, layers[0], 0, alpha);
    fx.draw(ctx, this);
    this.drawRuler(ctx);
    if (exp.state === 'ready') this.drawTags(ctx, exp);
  }

  drawSky(ctx) {
    if (!this.skyGrad) {
      const g = ctx.createLinearGradient(0, 0, 0, this.groundY);
      g.addColorStop(0, '#6fa6d6'); g.addColorStop(0.5, '#a9cbe6'); g.addColorStop(1, '#efe3cf');
      this.skyGrad = g;
    }
    ctx.fillStyle = this.skyGrad;
    ctx.fillRect(0, 0, this.W, this.groundY);
    const sun = ctx.createRadialGradient(this.W * 0.82, this.groundY * 0.28, 0, this.W * 0.82, this.groundY * 0.28, 260);
    sun.addColorStop(0, 'rgba(255,248,225,0.85)'); sun.addColorStop(0.2, 'rgba(255,240,205,0.35)'); sun.addColorStop(1, 'rgba(255,240,205,0)');
    ctx.fillStyle = sun;
    ctx.fillRect(0, 0, this.W, this.groundY);
  }

  drawFar(ctx) {
    const W = this.W, gy = this.groundY, S = this.S;
    const ridge = (par, base, amp, f1, f2, color) => {
      const off = this.camX * S * par;
      ctx.beginPath(); ctx.moveTo(0, gy);
      for (let x = 0; x <= W + 20; x += 20) {
        const u = (x + off) / S;
        ctx.lineTo(x, gy - base - amp * (Math.sin(u * f1) * 0.6 + Math.sin(u * f2 + 1.7) * 0.4));
      }
      ctx.lineTo(W, gy); ctx.closePath(); ctx.fillStyle = color; ctx.fill();
    };
    ridge(0.08, 70, 34, 0.11, 0.29, '#b3c8d4');
    // Test facility hangars
    const par = 0.2, off = this.camX * S * par;
    for (let i = Math.floor(off / 700) - 1; i <= Math.floor((off + W) / 700) + 1; i++) {
      const hs = hash32(i + 1000);
      const x = i * 700 - off + (hs % 200);
      const w = 180 + (hs >>> 8) % 140, h = 46 + (hs >>> 16) % 30;
      ctx.fillStyle = '#a4b3bd';
      ctx.fillRect(x, gy - h - 22, w, h + 22);
      ctx.beginPath(); ctx.moveTo(x - 6, gy - h - 22); ctx.lineTo(x + w / 2, gy - h - 44); ctx.lineTo(x + w + 6, gy - h - 22); ctx.fill();
      ctx.fillStyle = 'rgba(70,90,105,0.25)';
      for (let k = 0; k < 5; k++) ctx.fillRect(x + 14 + k * (w - 28) / 5, gy - h - 8, (w - 28) / 5 - 8, 10);
    }
    ridge(0.3, 16, 9, 0.8, 2.1, '#8faa92');
  }

  drawBoard(ctx, exp) {
    // Measurement backdrop behind the test zone: 0.5 m grid, 4 m tall.
    const S = this.S;
    const x0 = Math.max(this.sx(-14), -20), x1 = Math.min(this.sx(Math.max(exp.wallEnd + 16, 28)), this.W + 20);
    if (x1 <= x0) return;
    const top = this.sy(4), bottom = this.sy(0);
    ctx.fillStyle = 'rgba(250,248,242,0.42)';
    ctx.fillRect(x0, top, x1 - x0, bottom - top);
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let y = 0.5; y <= 4.001; y += 0.5) { const py = Math.round(this.sy(y)) + 0.5; ctx.moveTo(x0, py); ctx.lineTo(x1, py); }
    const first = Math.ceil((this.camX - 1) * 2) / 2;
    for (let x = first; x <= this.camX + this.viewW() + 1; x += 0.5) {
      const px = Math.round(this.sx(x)) + 0.5;
      if (px < x0 || px > x1) continue;
      ctx.moveTo(px, top); ctx.lineTo(px, bottom);
    }
    ctx.strokeStyle = 'rgba(60,85,110,0.13)';
    ctx.stroke();
    ctx.fillStyle = 'rgba(40,50,60,0.55)';
    ctx.fillRect(x0, top - 3, x1 - x0, 3);
  }

  drawGround(ctx, exp) {
    const W = this.W, H = this.H, gy = this.groundY + this.shakeY, S = this.S;
    const band = 20;
    const road = ctx.createLinearGradient(0, gy - band, 0, gy);
    road.addColorStop(0, '#9a9b9c'); road.addColorStop(1, '#78797b');
    ctx.fillStyle = road; ctx.fillRect(0, gy - band, W, band);
    ctx.fillStyle = '#3a3c40'; ctx.fillRect(0, gy, W, 22);
    ctx.fillStyle = '#6e5d4b'; ctx.fillRect(0, gy + 22, W, 8);
    const soil = ctx.createLinearGradient(0, gy + 30, 0, H);
    soil.addColorStop(0, '#5a4737'); soil.addColorStop(1, '#271f19');
    ctx.fillStyle = soil; ctx.fillRect(0, gy + 30, W, H - gy - 30);
    ctx.fillStyle = 'rgba(255,255,255,0.08)'; ctx.fillRect(0, gy, W, 1);

    // Start line (checkered) at the car's bumper start position.
    const sx0 = this.sx(SIM.wallX - SIM.runup);
    if (sx0 > -20 && sx0 < W + 20) {
      const cs = band / 4;
      for (let i = 0; i < 4; i++) for (let j = 0; j < 2; j++) {
        ctx.fillStyle = (i + j) % 2 ? '#111' : '#eee';
        ctx.fillRect(sx0 - cs * 2 + j * cs, gy - band + i * cs, cs, cs);
      }
    }

    // Distance ticks relative to the wall face.
    ctx.font = '600 10px ui-monospace, SFMono-Regular, Menlo, monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const m0 = Math.floor(this.camX) - 1, m1 = Math.ceil(this.camX + this.viewW()) + 1;
    for (let m = m0; m <= m1; m++) {
      const px = Math.round(this.sx(SIM.wallX + m)) + 0.5;
      const major = m % 5 === 0;
      ctx.strokeStyle = m === 0 ? '#ffb81c' : major ? 'rgba(255,255,255,0.7)' : 'rgba(255,255,255,0.35)';
      ctx.lineWidth = m === 0 ? 2 : 1;
      ctx.beginPath(); ctx.moveTo(px, gy); ctx.lineTo(px, gy + (major ? 9 : 5)); ctx.stroke();
      if (major || m === -1 || m === 1 || (m > 0 && m < 3)) {
        ctx.fillStyle = m === 0 ? '#ffb81c' : 'rgba(255,255,255,0.62)';
        ctx.fillText(m === 0 ? '0 m' : `${m}`, px, gy + 15);
      }
    }
  }

  drawSkids(ctx, exp) {
    const gy = this.groundY + this.shakeY;
    ctx.fillStyle = 'rgba(25,25,28,0.55)';
    for (let i = 0; i < 2; i++) {
      for (const [a, b] of exp.skids[i]) {
        const x0 = this.sx(Math.min(a, b)), x1 = this.sx(Math.max(a, b));
        if (x1 < -5 || x0 > this.W + 5) continue;
        ctx.fillRect(x0, gy - 7 - i * 2, Math.max(1, x1 - x0), 4);
      }
    }
  }

  drawLayer(ctx, bricks, k, alpha) {
    const S = this.S, fills = this.brickFills[Math.min(k, 4)];
    const ox = k * 3 + this.shakeX - this.camX * S, oy = -k * 4 + this.groundY + this.shakeY;
    const inset = 0.7 / S;
    const paths = [new Path2D(), new Path2D(), new Path2D(), new Path2D(), new Path2D(), new Path2D()];
    const lit = new Path2D(), dark = new Path2D();
    for (let i = 0; i < bricks.length; i++) {
      const b = bricks[i];
      const x = b.px + (b.x - b.px) * alpha, y = b.py + (b.y - b.py) * alpha, a = b.pa + (b.a - b.pa) * alpha;
      const c = Math.cos(a), s = Math.sin(a);
      const hw = (b.hw - inset) * S, hh = (b.hh - inset) * S;
      const cx = x * S + ox, cy = oy - y * S;
      const ux = c * hw, uy = -s * hw, vx = -s * hh, vy = -c * hh;
      const p = paths[b.shade];
      p.moveTo(cx - ux - vx, cy - uy - vy);
      p.lineTo(cx + ux - vx, cy + uy - vy);
      p.lineTo(cx + ux + vx, cy + uy + vy);
      p.lineTo(cx - ux + vx, cy - uy + vy);
      p.closePath();
      lit.moveTo(cx - ux + vx, cy - uy + vy); lit.lineTo(cx + ux + vx, cy + uy + vy);
      dark.moveTo(cx - ux - vx, cy - uy - vy); dark.lineTo(cx + ux - vx, cy + uy - vy);
    }
    for (let q = 0; q < 6; q++) { ctx.fillStyle = fills[q]; ctx.fill(paths[q]); }
    ctx.lineWidth = 1.3;
    ctx.strokeStyle = `rgba(255,214,180,${0.32 - k * 0.05})`; ctx.stroke(lit);
    ctx.strokeStyle = 'rgba(40,14,8,0.38)'; ctx.stroke(dark);
    ctx.lineWidth = 0.8;
    ctx.strokeStyle = 'rgba(52,26,18,0.55)';
    for (let q = 0; q < 6; q++) ctx.stroke(paths[q]);
  }

  drawCar(ctx, exp, alpha) {
    const car = exp.car, S = this.S, dpr = this.dpr, v = this.visual, crush = exp.crush;
    const x = car.px + (car.x - car.px) * alpha, y = car.py + (car.y - car.py) * alpha, a = car.pa + (car.a - car.pa) * alpha;
