/* =====================================================================
   8. APPLICATION: settings panel, controls, telemetry, main loop
   ===================================================================== */

const $ = (id) => document.getElementById(id);
const canvas = $('scene');
const renderer = new Renderer(canvas);
const fx = new Effects();
const staged = { ...DEFAULTS };
const controls = {};
let exp = new Experiment(staged);
let timeScale = 1;
let acc = 0;
let rebuildTimer = 0;
let hudTimer = 0;
const tmp = [0, 0];

function normalize(def, v) {
  if (!Number.isFinite(v)) v = staged[def.key];
  v = clamp(v, def.min, def.max);
  v = Math.round(v / def.step) * def.step;
  return +v.toFixed(def.dp);
}

function buildSliders() {
  for (const def of SCHEMA) {
    const host = $(def.group === 'core' ? 'coreSliders' : 'advSliders');
    const wrap = document.createElement('div');
    wrap.className = 'field';
    const id = `f-${def.key}`;
    wrap.innerHTML =
      `<div class="field-top"><label for="${id}">${def.label}</label>` +
      `<span class="num"><input type="number" inputmode="decimal" min="${def.min}" max="${def.max}" step="${def.step}" aria-label="${def.label} value">` +
      (def.unit ? `<span>${def.unit}</span>` : '') + `</span></div>` +
      `<input type="range" id="${id}" min="${def.min}" max="${def.max}" step="${def.step}">`;
    host.appendChild(wrap);
    const range = wrap.querySelector('input[type="range"]');
    const num = wrap.querySelector('input[type="number"]');
    controls[def.key] = { def, wrap, range, num };
    range.addEventListener('input', () => setStaged(def.key, parseFloat(range.value)));
    num.addEventListener('change', () => setStaged(def.key, parseFloat(num.value)));
    num.addEventListener('keydown', (e) => { if (e.key === 'Enter') num.blur(); });
  }
}

function syncControl(key) {
  const { def, range, num } = controls[key];
  const v = staged[key];
  range.value = v;
  num.value = v.toFixed(def.dp);
  range.style.setProperty('--fill', `${((v - def.min) / (def.max - def.min)) * 100}%`);
}

function setStaged(key, value) {
  staged[key] = normalize(controls[key].def, value);
  syncControl(key);
  if (exp.state === 'ready') {
    clearTimeout(rebuildTimer);
    rebuildTimer = setTimeout(() => loadScene(false), 90);
  }
  refreshParams();
}

function isPending(key) { return staged[key] !== exp.settings[key]; }

function refreshParams() {
  const a = exp.settings;
  let anyPending = false;
  for (const key of Object.keys(controls)) {
    const p = isPending(key);
    anyPending ||= p;
    controls[key].wrap.classList.toggle('changed', p);
  }
  $('pending').hidden = !anyPending;
  const d = (keys) => (keys.some(isPending) ? ' class="diff"' : '');
  const rows = [
    ['Car speed', `${a.carSpeed.toFixed(1)} m/s`, d(['carSpeed'])],
    ['Car mass', `${a.carMass.toLocaleString('en-US')} kg`, d(['carMass'])],
    ['Wall', `${a.cols} \u00d7 ${a.rows} \u00d7 ${a.layers}`, d(['cols', 'rows', 'layers'])],
    ['Brick mass', `${a.brickMass.toFixed(1)} kg`, d(['brickMass'])],
    ['Pieces', `${exp.pieces} \u00b7 ${exp.wallMass.toFixed(0)} kg`, d(['cols', 'rows', 'layers', 'brickMass'])],
    ['Gravity', `${a.gravity.toFixed(2)} m/s\u00b2`, d(['gravity'])],
    ['Brick \u03bc / e', `${a.brickFriction.toFixed(2)} / ${a.brickRestitution.toFixed(2)}`, d(['brickFriction', 'brickRestitution'])],
    ['Ground \u03bc', a.groundFriction.toFixed(2), d(['groundFriction'])],
    ['Car size', `${FIXED.carW.toFixed(2)} \u00d7 ${FIXED.carH.toFixed(2)} m`, ' class="fixed"'],
    ['Brick size', `${FIXED.brickW.toFixed(2)} \u00d7 ${FIXED.brickH.toFixed(2)} m`, ' class="fixed"'],
    ['Scale', `${FIXED.pxPerM} px/m`, ' class="fixed"'],
    ['Solver', `${Math.round(SIM.substeps / SIM.frameDt)} Hz \u00b7 ${SIM.velIters}+${SIM.posIters} it`, ' class="fixed"'],
  ];
  $('paramList').innerHTML = rows.map(([k, v, c]) => `<dt>${k}</dt><dd${c}>${v}</dd>`).join('');
  const baseline = Object.keys(DEFAULTS).every((k) => a[k] === DEFAULTS[k]);
  $('paramState').textContent = baseline ? 'mandatory baseline' : 'custom';
}

function loadScene(run) {
  clearTimeout(rebuildTimer);
  exp = new Experiment(staged);
  renderer.frame(exp);
  fx.reset();
  acc = 0;
  hideVerdict();
  if (run) exp.start();
  refreshParams();
  updateHud();
}

function hideVerdict() { $('verdict').classList.remove('show'); }

function showVerdict() {
  const el = $('verdict');
  el.innerHTML = exp.verdict();
  el.style.top = `${document.querySelector('.telemetry').getBoundingClientRect().bottom + 10}px`;
  el.classList.add('show');
}

function setPressed(id, on) { $(id).setAttribute('aria-pressed', on ? 'true' : 'false'); }

function setFollow(on) {
  renderer.follow = on;
  setPressed('btnFollow', on);
}

function toggleSlow() {
  timeScale = timeScale === 1 ? 0.25 : 1;
  setPressed('btnSlow', timeScale !== 1);
}

function toggleSettings() {
  const hidden = document.body.classList.toggle('dock-hidden');
  setPressed('btnSettings', !hidden);
  layout();
}

function layout() {
  const dockHidden = document.body.classList.contains('dock-hidden');
  const reserve = dockHidden ? 70 : $('dock').getBoundingClientRect().height + 12 + 44;
  renderer.resize(reserve);
  renderer.home(exp);
  if (exp.state === 'ready' && renderer.follow) renderer.camX = renderer.camHome;
  sizeSpark();
}

/* ---------- telemetry ---------- */

const STATUS_LABEL = { ready: 'Ready', launch: 'Launch', impact: 'Impact', settled: 'Settled' };
const spark = $('spark');
const sparkCtx = spark.getContext('2d');

function sizeSpark() {
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  spark.width = Math.max(1, Math.round(spark.clientWidth * dpr));
  spark.height = Math.max(1, Math.round(spark.clientHeight * dpr));
}

function drawSpark() {
  const w = spark.width, h = spark.height, c = sparkCtx;
  c.clearRect(0, 0, w, h);
  if (!w || !h) return;
  const hist = exp.history;
  const tMax = Math.max(4, hist.length * SIM.frameDt);
  const vMax = Math.max(exp.settings.carSpeed, ...(hist.length ? [Math.max(...hist)] : [0])) * 1.12;
  const X = (t) => (t / tMax) * w, Y = (v) => h - 2 - (v / vMax) * (h - 4);
  c.setLineDash([3, 3]); c.strokeStyle = 'rgba(255,255,255,0.22)'; c.lineWidth = 1;
  c.beginPath(); c.moveTo(0, Y(exp.settings.carSpeed)); c.lineTo(w, Y(exp.settings.carSpeed)); c.stroke();
  c.setLineDash([]);
  if (exp.impactT !== null) {
    c.strokeStyle = 'rgba(255,91,58,0.8)';
    c.beginPath(); c.moveTo(X(exp.impactT), 0); c.lineTo(X(exp.impactT), h); c.stroke();
  }
  if (hist.length > 1) {
    c.strokeStyle = '#ffb81c'; c.lineWidth = 1.6 * (w / spark.clientWidth || 1);
    c.beginPath();
    for (let i = 0; i < hist.length; i++) { const x = X((i + 1) * SIM.frameDt), y = Y(hist[i]); i ? c.lineTo(x, y) : c.moveTo(x, y); }
    c.stroke();
  }
}

function updateHud() {
  const car = exp.car;
  const speed = Math.hypot(car.vx, car.vy);
  const st = $('telStatus');
  st.dataset.state = exp.state;
  st.textContent = STATUS_LABEL[exp.state];
  $('telSpeed').textContent = speed.toFixed(1);
  $('telKmh').textContent = `${Math.round(speed * 3.6)} km/h`;
  $('telTime').innerHTML = `${exp.t.toFixed(2)}<small>s</small>`;
  $('telMoving').innerHTML = `${exp.moving}<small>/ ${exp.pieces}</small>`;
  const hit = exp.impactT !== null;
  $('telImpact').innerHTML = hit ? `${exp.impactSpeed.toFixed(1)}<small>m/s</small>` : '&mdash;';
  $('telPeak').innerHTML = hit ? `${exp.peakDecel.toFixed(1)}<small>g</small>` : '&mdash;';
  $('telDisp').innerHTML = hit ? `${Math.round((100 * exp.displaced) / exp.pieces)}<small>% \u00b7 ${exp.displaced}</small>` : '&mdash;';
  $('telTravel').innerHTML = hit ? `${(exp.carFrontX() - SIM.wallX).toFixed(2)}<small>m</small>` : '&mdash;';
  $('telCrush').innerHTML = hit ? `${Math.round(exp.crush * 100)}<small>cm</small>` : '&mdash;';
  drawSpark();
}

/* ---------- input ---------- */

$('btnTest').addEventListener('click', () => loadScene(true));
$('btnReset').addEventListener('click', () => loadScene(false));
$('btnSlow').addEventListener('click', toggleSlow);
$('btnFollow').addEventListener('click', () => {
  setFollow(!renderer.follow);
  if (renderer.follow && exp.state === 'ready') renderer.camX = renderer.camHome;
});
$('btnSettings').addEventListener('click', toggleSettings);
$('btnDefaults').addEventListener('click', () => {
  Object.assign(staged, DEFAULTS);
  for (const key of Object.keys(controls)) syncControl(key);
  if (exp.state === 'ready') loadScene(false); else refreshParams();
});

window.addEventListener('keydown', (e) => {
  const t = e.target;
  if (t instanceof HTMLInputElement && t.type === 'number') return;
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  const k = e.key.toLowerCase();
  if ((k === ' ' || k === 'enter') && !(t instanceof HTMLButtonElement)) { e.preventDefault(); loadScene(true); }
  else if (k === 'r') loadScene(false);
  else if (k === 's') toggleSlow();
  else if (k === 'f') $('btnFollow').click();
  else if (k === 'h') toggleSettings();
});

let drag = null;
canvas.addEventListener('pointerdown', (e) => {
  drag = { x: e.clientX, cam: renderer.camX, moved: false };
  canvas.setPointerCapture(e.pointerId);
  canvas.classList.add('dragging');
});
canvas.addEventListener('pointermove', (e) => {
  if (!drag) return;
  const dx = e.clientX - drag.x;
  if (!drag.moved && Math.abs(dx) > 3) { drag.moved = true; setFollow(false); }
  if (drag.moved) renderer.camX = drag.cam - dx / renderer.S;
});
const endDrag = () => { drag = null; canvas.classList.remove('dragging'); };
canvas.addEventListener('pointerup', endDrag);
canvas.addEventListener('pointercancel', endDrag);
canvas.addEventListener('dblclick', () => { setFollow(true); if (exp.state === 'ready') renderer.camX = renderer.camHome; });

window.addEventListener('resize', layout);
new ResizeObserver(layout).observe($('dock'));

/* ---------- main loop ---------- */

let last = performance.now();
function tick(now) {
  const dt = Math.min(0.1, (now - last) / 1000);
  last = now;
  let steps = 0;
  if (exp.running) {
    acc += dt * timeScale;
    while (acc >= SIM.frameDt && steps < 4 && exp.running) {
      exp.snapshot();
      exp.stepFrame();
      acc -= SIM.frameDt;
      steps++;
      fx.ingest(exp.world.events, renderer);
      if (exp.world.wheelsLocked) {
        const sp = Math.abs(exp.car.vx);
        for (let i = 0; i < 2; i++) if (exp.world.wheelContact[i] && sp > 1.5) fx.tyreSmoke(exp.wheelCenter(i, tmp)[0], sp);
      }
    }
    if (steps === 4) acc = Math.min(acc, SIM.frameDt);
    if (!exp.running) { acc = 0; updateHud(); showVerdict(); }
  }
  const alpha = exp.running ? clamp(acc / SIM.frameDt, 0, 1) : 1;
  fx.update(dt * timeScale);
  renderer.update(dt, steps * SIM.frameDt, exp);
  renderer.draw(exp, fx, alpha);
  hudTimer -= dt;
  if (hudTimer <= 0 && exp.running) { updateHud(); hudTimer = 0.08; }
  requestAnimationFrame(tick);
}

/* ---------- scripting / verification hook ---------- */

window.crashLab = {
  defaults: DEFAULTS,
  get staged() { return { ...staged }; },
  get active() { return { ...exp.settings }; },
  summary: () => exp.summary(),
  test: () => loadScene(true),
  reset: () => loadScene(false),
  // Runs a separate headless experiment to completion; does not touch the view.
  simulate(overrides = {}, seconds = SIM.maxTime) {
    const e = new Experiment({ ...DEFAULTS, ...overrides });
    e.start();
    const frames = Math.round(seconds / SIM.frameDt);
    for (let i = 0; i < frames && e.running; i++) e.stepFrame();
    return e.summary();
  },
};

buildSliders();
for (const key of Object.keys(controls)) syncControl(key);
layout();
renderer.frame(exp);
refreshParams();
updateHud();
requestAnimationFrame(tick);

