    range.addEventListener('input', () => setStaged(def.key, parseFloat(range.value)));
    num.addEventListener('change', () => setStaged(def.key, parseFloat(num.value)));
    num.addEventListener('keydown', (e) => { if (e.key === 'Enter') num.blur(); });
  }
}

function syncControl(key) {
  const { def, range, num } = controls[key];
  const v = staged[key];
  range.value = v;
  num.value = v.toFixed(def.dp);
  range.style.setProperty('--fill', `${((v - def.min) / (def.max - def.min)) * 100}%`);
}

function setStaged(key, value) {
  staged[key] = normalize(controls[key].def, value);
  syncControl(key);
  if (exp.state === 'ready') {
    clearTimeout(rebuildTimer);
    rebuildTimer = setTimeout(() => loadScene(false), 90);
  }
  refreshParams();
}

function isPending(key) { return staged[key] !== exp.settings[key]; }

function refreshParams() {
  const a = exp.settings;
  let anyPending = false;
  for (const key of Object.keys(controls)) {
    const p = isPending(key);
    anyPending ||= p;
    controls[key].wrap.classList.toggle('changed', p);
  }
  $('pending').hidden = !anyPending;
  const d = (keys) => (keys.some(isPending) ? ' class="diff"' : '');
  const rows = [
    ['Car speed', `${a.carSpeed.toFixed(1)} m/s`, d(['carSpeed'])],
    ['Car mass', `${a.carMass.toLocaleString('en-US')} kg`, d(['carMass'])],
    ['Wall', `${a.cols} \u00d7 ${a.rows} \u00d7 ${a.layers}`, d(['cols', 'rows', 'layers'])],
    ['Brick mass', `${a.brickMass.toFixed(1)} kg`, d(['brickMass'])],
    ['Pieces', `${exp.pieces} \u00b7 ${exp.wallMass.toFixed(0)} kg`, d(['cols', 'rows', 'layers', 'brickMass'])],
    ['Gravity', `${a.gravity.toFixed(2)} m/s\u00b2`, d(['gravity'])],
    ['Brick \u03bc / e', `${a.brickFriction.toFixed(2)} / ${a.brickRestitution.toFixed(2)}`, d(['brickFriction', 'brickRestitution'])],
    ['Ground \u03bc', a.groundFriction.toFixed(2), d(['groundFriction'])],
    ['Car size', `${FIXED.carW.toFixed(2)} \u00d7 ${FIXED.carH.toFixed(2)} m`, ' class="fixed"'],
    ['Brick size', `${FIXED.brickW.toFixed(2)} \u00d7 ${FIXED.brickH.toFixed(2)} m`, ' class="fixed"'],
    ['Scale', `${FIXED.pxPerM} px/m`, ' class="fixed"'],
    ['Solver', `${Math.round(SIM.substeps / SIM.frameDt)} Hz \u00b7 ${SIM.velIters}+${SIM.posIters} it`, ' class="fixed"'],
  ];
  $('paramList').innerHTML = rows.map(([k, v, c]) => `<dt>${k}</dt><dd${c}>${v}</dd>`).join('');
  const baseline = Object.keys(DEFAULTS).every((k) => a[k] === DEFAULTS[k]);
  $('paramState').textContent = baseline ? 'mandatory baseline' : 'custom';
}

function loadScene(run) {
  clearTimeout(rebuildTimer);
  exp = new Experiment(staged);
  renderer.frame(exp);
  fx.reset();
  acc = 0;
  hideVerdict();
  if (run) exp.start();
  refreshParams();
  updateHud();
}

function hideVerdict() { $('verdict').classList.remove('show'); }

function showVerdict() {
  const el = $('verdict');
  el.innerHTML = exp.verdict();
  el.style.top = `${document.querySelector('.telemetry').getBoundingClientRect().bottom + 10}px`;
  el.classList.add('show');
}

function setPressed(id, on) { $(id).setAttribute('aria-pressed', on ? 'true' : 'false'); }

function setFollow(on) {
  renderer.follow = on;
  setPressed('btnFollow', on);
}

function toggleSlow() {
  timeScale = timeScale === 1 ? 0.25 : 1;
  setPressed('btnSlow', timeScale !== 1);
}

function toggleSettings() {
  const hidden = document.body.classList.toggle('dock-hidden');
  setPressed('btnSettings', !hidden);
  layout();
}

function layout() {
  const dockHidden = document.body.classList.contains('dock-hidden');
  const reserve = dockHidden ? 70 : $('dock').getBoundingClientRect().height + 12 + 44;
  renderer.resize(reserve);
  renderer.home(exp);
  if (exp.state === 'ready' && renderer.follow) renderer.camX = renderer.camHome;
  sizeSpark();
}

/* ---------- telemetry ---------- */

const STATUS_LABEL = { ready: 'Ready', launch: 'Launch', impact: 'Impact', settled: 'Settled' };
const spark = $('spark');
const sparkCtx = spark.getContext('2d');

function sizeSpark() {
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  spark.width = Math.max(1, Math.round(spark.clientWidth * dpr));
  spark.height = Math.max(1, Math.round(spark.clientHeight * dpr));
}

function drawSpark() {
  const w = spark.width, h = spark.height, c = sparkCtx;
  c.clearRect(0, 0, w, h);
  if (!w || !h) return;
  const hist = exp.history;
  const tMax = Math.max(4, hist.length * SIM.frameDt);
  const vMax = Math.max(exp.settings.carSpeed, ...(hist.length ? [Math.max(...hist)] : [0])) * 1.12;
  const X = (t) => (t / tMax) * w, Y = (v) => h - 2 - (v / vMax) * (h - 4);
  c.setLineDash([3, 3]); c.strokeStyle = 'rgba(255,255,255,0.22)'; c.lineWidth = 1;
  c.beginPath(); c.moveTo(0, Y(exp.settings.carSpeed)); c.lineTo(w, Y(exp.settings.carSpeed)); c.stroke();
  c.setLineDash([]);
  if (exp.impactT !== null) {
    c.strokeStyle = 'rgba(255,91,58,0.8)';
    c.beginPath(); c.moveTo(X(exp.impactT), 0); c.lineTo(X(exp.impactT), h); c.stroke();
