    this.settings = Object.freeze({ ...settings });
    const w = (this.world = new World(this.settings));
    this.car = buildCar(w, this.settings);
    buildWall(w, this.settings);
    w.prestress(SIM.frameDt / SIM.substeps, 40);

    this.pieces = w.bricks.length;
    this.wallMass = w.bricks.reduce((sum, b) => sum + b.mass, 0);
    this.wallEnd = SIM.wallX + this.settings.cols * FIXED.brickW;
    this.state = 'ready';
    this.t = 0;
    this.frame = 0;
    // Tow sled: constant acceleration reaching the set speed cruiseLead metres before the wall.
    this.launchA = Math.max(this.settings.carSpeed ** 2 / (2 * (SIM.runup - SIM.cruiseLead)), 1.5);
    this.impactT = null;
    this.impactSpeed = null;
    this.impactKE = 0;
    this.freeSpeed = 0;
    this.peakDecel = 0;
    this.slide = 0;
    this.crush = 0;
    this.settleTimer = 0;
    this.minVxAfter = 0;
    this.maxFront = -Infinity;
    this.moving = 0;
    this.displaced = 0;
    this.history = [];
    this.skids = [[], []];
    this.skidOpen = [null, null];
    this.touchFrame = false;
    this.impactFrame = false;
    this._pt = [0, 0];
  }

  get running() { return this.state === 'launch' || this.state === 'impact'; }

  start() { if (this.state === 'ready') this.state = 'launch'; }

  carFrontX() {
    return carPoint(this.car, CAR_DESIGN.front - this.crush, 0.52, this._pt)[0];
  }

  wheelCenter(i, out) {
    return carPoint(this.car, CAR_DESIGN.wheelX[i], WHEEL_AP, out);
  }

  snapshot() {
    const bodies = this.world.bodies;
    for (let i = 0; i < bodies.length; i++) { const b = bodies[i]; b.px = b.x; b.py = b.y; b.pa = b.a; }
  }

  stepFrame() {
    if (!this.running) return;
    const w = this.world, car = this.car, s = this.settings;
    const h = SIM.frameDt / SIM.substeps;
    w.events.length = 0;
    this.touchFrame = false;
    this.impactFrame = false;
    const vxStart = car.vx;

    for (let i = 0; i < SIM.substeps; i++) {
      if (this.state === 'launch') {
        const vDes = Math.min(s.carSpeed, this.launchA * (this.t + h));
        car.fx = clamp((car.mass * (vDes - car.vx)) / h, 0, car.mass * (this.launchA * 3 + 30));
      } else {
        car.fx = 0;
      }
      w.substep(h);
      this.t += h;
      if (!w.carNear && this.state === 'launch') this.freeSpeed = car.vx;
      if (w.carTouch) this.touchFrame = true;
      if (this.state === 'launch' && w.carTouch) {
        const v0 = this.freeSpeed;
        this.state = 'impact';
        this.impactT = this.t;
        this.impactSpeed = v0;
        this.impactKE = 0.5 * car.mass * v0 * v0;
        this.impactFrame = true;
        car.fx = 0;
        w.wheelsLocked = true;   // brakes lock on impact
      }
      if (w.wheelsLocked && (w.wheelContact[0] || w.wheelContact[1])) this.slide += Math.abs(car.vx) * h;
    }
    this.frame++;

    if (this.impactT !== null) {
      const decel = -(car.vx - vxStart) / SIM.frameDt / G0;
      if (decel > this.peakDecel) this.peakDecel = decel;
      if (this.touchFrame) {
        // Plastic crumple: grows with the kinetic energy the car has lost to the wall.
        const ke = 0.5 * car.mass * (car.vx * car.vx + car.vy * car.vy) + 0.5 * car.I * car.w * car.w;
        const E = this.impactKE - ke - s.groundFriction * car.mass * s.gravity * this.slide;
        const target = SIM.crushMax * (1 - Math.exp(-Math.max(0, E) / SIM.crushE0));
        if (target > this.crush + 0.002) { this.crush = target; setCrush(car, target); }
      }
      this.minVxAfter = Math.min(this.minVxAfter, car.vx);
      this.maxFront = Math.max(this.maxFront, this.carFrontX());
      if (this.t - this.impactT > 0.4) car.canSleep = true;
    }

    this.updateSkids();

    let moving = 0;
    const bricks = w.bricks;
    for (let i = 0; i < bricks.length; i++) { const b = bricks[i]; if (!b.sleeping && b.motion2 > 0.0025) moving++; }
    this.moving = moving;
    if (this.frame % 6 === 0) this.countDisplaced();

    const speed = Math.hypot(car.vx, car.vy);
    this.history.push(speed);

    if (this.state === 'impact') {
      if (moving === 0 && speed < 0.05) this.settleTimer += SIM.frameDt;
      else this.settleTimer = 0;
      if (this.settleTimer >= SIM.settleTime || this.t >= SIM.maxTime) this.finish();
    } else if (this.state === 'launch' && this.t > 15) {
      this.finish();
    }
  }

  finish() {
    this.state = 'settled';
    this.car.fx = 0;
    this.countDisplaced();
  }

  countDisplaced() {
    let n = 0;
    const bricks = this.world.bricks;
    for (let i = 0; i < bricks.length; i++) {
      const b = bricks[i];
      // Counted once a piece has moved half a brick length or tipped past 20 degrees.
      const dx = b.x - b.x0, dy = b.y - b.y0;
      if (dx * dx + dy * dy > 0.0625 || Math.abs(b.a - b.a0) > 0.35) n++;
    }
    this.displaced = n;
  }

  updateSkids() {
    const w = this.world, car = this.car;
    for (let i = 0; i < 2; i++) {
      const sliding = w.wheelsLocked && w.wheelContact[i] && Math.abs(car.vx) > 0.15;
      if (!sliding) { this.skidOpen[i] = null; continue; }
      const x = this.wheelCenter(i, this._pt)[0];
      if (!this.skidOpen[i]) { const seg = [x, x]; this.skids[i].push(seg); this.skidOpen[i] = seg; }
      else this.skidOpen[i][1] = x;
    }
  }

  stateHash() {
    let h = 2166136261;
    const mix = (v) => { h ^= Math.round(v * 1e6) | 0; h = Math.imul(h, 16777619); };
    for (const b of this.world.bodies) { mix(b.x); mix(b.y); mix(b.a); mix(b.vx); mix(b.vy); }
    return (h >>> 0).toString(16).padStart(8, '0');
  }

  verdict() {
    if (this.impactT === null) return '';
    const f = this.displaced / this.pieces;
    const past = this.maxFront - SIM.wallX;
    let head;
    if (this.maxFront > this.wallEnd + 0.3) head = 'Car broke through the whole wall';
    else if (f > 0.5) head = 'Wall collapsed';
    else if (f > 0.04) head = 'Partial collapse';
    else head = 'Wall held';
    const parts = [
      `<b>${head}.</b> ${this.displaced} of ${this.pieces} pieces displaced (${Math.round(f * 100)}%)`,
      `car front reached ${past.toFixed(2)} m past the wall face`,
      `peak decel. ${this.peakDecel.toFixed(1)} g`,
    ];
    if (this.minVxAfter < -0.2) parts.push(`recoil ${(-this.minVxAfter).toFixed(1)} m/s`);
    return parts.join(' &middot; ');
  }

  summary() {
    const car = this.car;
    return {
      state: this.state,
      t: +this.t.toFixed(4),
      impactT: this.impactT === null ? null : +this.impactT.toFixed(4),
      impactSpeed: this.impactSpeed === null ? null : +this.impactSpeed.toFixed(3),
      carX: +car.x.toFixed(4),
      carVx: +car.vx.toFixed(4),
      carAngleDeg: +((car.a * 180) / Math.PI).toFixed(2),
      maxFrontPastWall: this.maxFront === -Infinity ? null : +(this.maxFront - SIM.wallX).toFixed(3),
      peakDecelG: +this.peakDecel.toFixed(2),
      crush: +this.crush.toFixed(3),
      pieces: this.pieces,
      displaced: this.displaced,
      moving: this.moving,
      minBrickY: +Math.min(...this.world.bricks.map((b) => b.minY)).toFixed(4),
      hash: this.stateHash(),
    };
  }
}

